insert into "il_lessons" ("id", "short_id", "source_video_id", "title", "level", "topic", "start_ms", "end_ms", "gist_prompt", "gist_options", "gist_answer", "gist_explain", "intro", "focus", "status", "is_premium", "note", "sort", "date_created", "date_updated", "slug", "explore", "gist_sentences") select "id", "short_id", "source_video_id", "title", "level", "topic", "start_ms", "end_ms", "gist_prompt", "gist_options", "gist_answer", "gist_explain", "intro", "focus", "status", "is_premium", "note", "sort", "date_created", "date_updated", "slug", "explore", "gist_sentences" from jsonb_populate_recordset(null::"il_lessons", $sync$[{"id":"3fb72aa8-9f92-408e-b1c6-b26b71312916","note":null,"slug":"wills-letter-to-clark","sort":0,"focus":"linking","intro":"Có những lời người ta chỉ kịp viết ra. Đây là phần cuối một lá thư trong phim Me Before You.","level":1,"title":"Lá thư cuối dặn một người điều gì?","topic":null,"end_ms":355510,"status":"published","explore":"## Bộ phim\r\nMe Before You ra mắt năm 2016, dựa trên tiểu thuyết cùng tên của Jojo Moyes. Emilia Clarke đóng Louisa Clark, một cô gái vui tính nhận việc chăm sóc Will Traynor, chàng trai bị liệt sau một tai nạn. Will do Sam Claflin đóng.\r\n\r\n## Lá thư\r\nSau khi Will qua đời, Louisa đọc lá thư anh để lại tại một quán cà phê ở Paris, đúng như anh dặn. Anh nhắc đến khoản tiền giúp cô bắt đầu lại, và mong cô dám sống rộng hơn.\r\n\r\n## Cách nói đáng nhớ\r\n- \"Wear those stripy legs with pride\": cứ tự hào là chính mình, kể cả với đôi tất sọc.\r\n- \"You are scored on my heart\": hình bóng em đã khắc vào tim anh.\r\n- \"Just live well\": cứ sống thật tốt.\r\n\r\nVideo ghép đoạn thư này sau một bài hát, nên phần luyện nghe chỉ lấy đoạn đọc thư, nơi giọng nói rõ và chậm.","short_id":"c7a165a6","start_ms":303759,"is_premium":false,"gist_answer":0,"gist_prompt":"Người viết thư muốn người đọc làm gì?","date_created":"2026-11-25T11:31:17.337255+00:00","date_updated":"2026-11-25T11:34:30.883644+00:00","gist_explain":"Lá thư dặn đừng nghĩ về người viết quá nhiều, đừng buồn, cứ sống thật tốt.","gist_options":["Cứ sống thật tốt và đừng buồn vì mình","Hoảng lên và đi tìm mình ngay","Luôn nghĩ về mình mỗi khi thấy buồn"],"gist_sentences":[7,8,9],"source_video_id":"7ee7ebc2-01b8-468b-8d2a-cca78882a25a"},{"id":"d15579dc-1aca-4883-a327-b1e083d437e1","note":null,"slug":"when-love-feels-too-intense","sort":0,"focus":"linking","intro":"Cảm giác \"như trúng số\" lúc mới yêu có phải lúc nào cũng là dấu hiệu tốt?","level":2,"title":"Tình yêu quá mãnh liệt có đáng lo không?","topic":null,"end_ms":284333,"status":"draft","explore":"## Bài nói\r\nKatie Hood làm việc tại tổ chức One Love, nơi giúp người trẻ nhận ra các dấu hiệu của một mối quan hệ không lành mạnh. Trong bài TED này, cô cho rằng ai cũng có lúc làm điều chưa tốt với người mình thương, và điều quan trọng là biết nhận ra để sửa.\r\n\r\n## Dấu hiệu đầu tiên: quá mãnh liệt\r\nMối quan hệ độc hại thường không xấu ngay từ đầu. Nó bắt đầu bằng sự hào hứng, rồi dần chuyển sang choáng ngợp và ngột ngạt, ví dụ khi người kia liên tục xuất hiện, nhắn tin, gọi điện và khó chịu khi bạn trả lời chậm. Cô khuyên rằng điều đáng xem không phải mối quan hệ bắt đầu ngọt ngào ra sao, mà là về sau nó thay đổi theo hướng nào.\r\n\r\n## Tự hỏi mình\r\n- Mình có thoải mái với tốc độ gần gũi này không?\r\n- Mình có còn không gian riêng không?\r\n- Khi mình nói ra điều mình cần, người kia có tôn trọng không?","short_id":"42ff61a0","start_ms":221850,"is_premium":false,"gist_answer":2,"gist_prompt":"Khi mới bắt đầu một mối quan hệ, người nói khuyên điều gì?","date_created":"2026-11-25T11:36:09.139817+00:00","date_updated":"2026-11-25T11:36:09.823151+00:00","gist_explain":"Người nói khuyên chú ý cảm giác của mình và tập nói về nhu cầu của bản thân.","gist_options":["Càng mãnh liệt thì càng chắc đó là tình yêu tốt","Đừng đòi hỏi gì để người kia luôn thấy vui","Để ý cảm xúc của mình và nói ra điều mình cần"],"gist_sentences":[8,11],"source_video_id":"1b0dae7c-8011-416b-9ae9-c44896c9e3cf"},{"id":"bfd37ff0-5b16-4600-81ce-3fada909932d","note":null,"slug":"can-confidence-be-trained","sort":0,"focus":"linking","intro":"Có người tin tài năng là trời cho, có người tin nó lớn lên được. Niềm tin đó thay đổi nhiều hơn bạn nghĩ.","level":1,"title":"Sự tự tin có rèn được như cơ bắp không?","topic":null,"end_ms":183606,"status":"draft","explore":"## Tự tin từ đâu ra\r\nVideo của TED-Ed cho rằng sự tự tin đến từ ba nguồn: thứ bạn sinh ra đã có, cách người khác đối xử với bạn, và những lựa chọn của chính bạn. Phần cuối cùng là phần bạn điều khiển được.\r\n\r\n## Ba mẹo\r\n- Cách nhanh: hình dung mình thành công, nghe nhạc, đứng ở tư thế mạnh mẽ, tự động viên.\r\n- Tin rằng mình tiến bộ được.\r\n- Tập thất bại: ai cũng có lúc sai.\r\n\r\n## Hai kiểu tư duy\r\nNgười có tư duy cố định nghĩ tài năng không đổi, nên dễ bỏ cuộc. Người có tư duy phát triển coi thử thách là dịp để học. Video cũng nhắc J.K. Rowling từng bị nhiều nhà xuất bản từ chối trước khi Harry Potter được nhận. Theo video, não bộ thật sự thay đổi khi ta học và luyện tập, nên mỗi lần làm sai cũng là một bước giúp ta quen với khó khăn.","short_id":"b516947f","start_ms":113396,"is_premium":false,"gist_answer":2,"gist_prompt":"Vì sao cách bạn nghĩ về khả năng của mình lại quan trọng?","date_created":"2026-11-25T11:36:10.753418+00:00","date_updated":"2026-11-25T11:36:11.399982+00:00","gist_explain":"Người nói bảo niềm tin này ảnh hưởng đến cách bạn hành động khi gặp trở ngại.","gist_options":["Vì khả năng đã cố định từ lúc bạn mới sinh ra","Vì nghĩ tích cực thì bạn sẽ không bao giờ thất bại","Vì nó ảnh hưởng đến cách bạn phản ứng khi gặp trở ngại"],"gist_sentences":[5],"source_video_id":"abe26327-5afe-42c5-8b27-cfda9d49d2b8"}]$sync$::jsonb) on conflict do nothing;
do $do$ begin
