  if not found and not exists (select 1 from "il_lessons" t, jsonb_populate_record(null::"il_lessons", $sync${"id":"a9f2f481-b123-4144-b020-cbe8b79f1aaa","note":null,"slug":"how-emotionally-healthy-are-you","sort":0,"focus":"linking","intro":"Bạn có thể kiểm tra sức khỏe cảm xúc bằng một danh sách câu hỏi rất đơn giản, không cần xét nghiệm.","level":2,"title":"Những câu hỏi để biết bạn khỏe về cảm xúc đến đâu","topic":null,"end_ms":259429,"status":"published","explore":"## Sức khỏe cảm xúc có các dấu hiệu\r\nThe School of Life gợi ý đánh giá mức độ tổn thương cảm xúc bằng một vài chủ đề chính. Đoạn bạn vừa nghe nói về hai chủ đề: sự tin tưởng và cách ta yêu.\r\n\r\n## Tin tưởng (Trust)\r\n- Thế giới nguy hiểm đến đâu?\r\n- Ta gần với thảm họa đến mức nào?\r\n- Người mới quen sẽ thích hay làm tổn thương ta?\r\n- Nếu ta hơi quả quyết, họ sẽ chấp nhận hay gục ngã?\r\n- Những tình huống lạ có kết thúc thảm hại không?\r\n\r\n## Tình yêu\r\n- Trong tình yêu, ta cần bám chặt đến mức nào?\r\n- Nếu họ xa cách một thời gian, họ có quay lại không?\r\n- Ta cần kiểm soát đến mức nào?\r\n- Ta có dám lại gần một người lạ thú vị, hay rời khỏi một người không thỏa mãn?\r\n\r\n## Cách dùng\r\nVới mỗi câu, thử trả lời trung thực. Câu trả lời cho thấy bạn đang sống với bao nhiêu nỗi lo thường trực.","short_id":"77000c53","start_ms":230961,"is_premium":false,"gist_answer":0,"gist_prompt":"Câu hỏi nào thuộc về tình yêu?","date_created":"2026-11-23T04:03:42.581785+00:00","date_updated":"2026-11-25T09:29:34.637805+00:00","gist_explain":"\"If they are distant for a while, will they return?\"","gist_options":["Nếu họ xa cách một thời gian, họ có quay lại không?","Người mới quen có thích ta không?","Thế giới nguy hiểm đến đâu?"],"gist_sentences":[7],"source_video_id":"1050f046-669c-424e-aea3-895bfe9e00b7"}$sync$::jsonb) n where t."id" = n."id" and t."date_updated"::text is not distinct from n."date_updated"::text) then
