do $do$ begin
  update "il_lessons" t set "status" = n."status", "date_updated" = n."date_updated"
    from jsonb_populate_record(null::"il_lessons", $sync${"id":"8697a61b-9d6d-4265-98c1-565fe58f539e","note":null,"slug":"saying-where-you-live","sort":0,"focus":"linking","intro":"Ở Anh, người trẻ rất hay thuê chung nhà với bạn bè hoặc cả người lạ. Hãy nghe bốn người kể họ sống ở đâu và sống với ai.","level":1,"title":"Bạn sống một mình hay ở ghép?","topic":null,"end_ms":182088,"status":"draft","explore":"## Hai câu hỏi rất hay gặp\r\nKhi làm quen, người Anh hay hỏi hai câu: \"Where do you live?\" (Bạn sống ở đâu?) và \"Who do you live with?\" (Bạn sống với ai?). Khi nói nhanh, \"do you\" gần như thành \"də-jə\", nên nghe cả câu như \"Where-də-jə-live?\".\r\n\r\n## House hay flat?\r\n- **house:** một ngôi nhà riêng, thường có nhiều tầng.\r\n- **flat:** căn hộ trong một tòa nhà. Người Mỹ gọi là apartment, người Anh gọi là flat.\r\n\r\n## Sống với ai?\r\n- **with my family:** với gia đình.\r\n- **with my housemates:** với những người ở chung nhà (house).\r\n- **with my flatmates:** với những người ở chung căn hộ (flat).\r\n- **on my own:** một mình, giống \"alone\" nhưng tự nhiên hơn khi nói.\r\n\r\n## Trong video\r\nBốn người dẫn chương trình của BBC Learning English kể về nơi họ sống: Tim và Georgie ở London, Sian ở Brighton, Buli ở Cambridge. Thuê nhà ở ghép rất phổ biến với người trẻ ở Anh vì giá thuê nhà ở các thành phố lớn như London rất cao.","short_id":"f0b1ac2d","start_ms":139530,"is_premium":false,"gist_answer":2,"gist_prompt":"Ai sống một mình?","date_created":"2026-11-23T04:03:35.296989+00:00","date_updated":"2026-11-25T08:35:58.660869+00:00","gist_explain":"Buli: \"I live in a flat in Cambridge ... I live on my own.\"","gist_options":["Georgie","Sian","Buli"],"gist_sentences":[7,10],"source_video_id":"301cb966-9acb-4a62-8664-6c23ab7db265"}$sync$::jsonb) n, jsonb_populate_record(null::"il_lessons", $sync${"id":"8697a61b-9d6d-4265-98c1-565fe58f539e","note":null,"slug":"saying-where-you-live","sort":0,"focus":"linking","intro":"Ở Anh, người trẻ rất hay thuê chung nhà với bạn bè hoặc cả người lạ. Hãy nghe bốn người kể họ sống ở đâu và sống với ai.","level":1,"title":"Bạn sống một mình hay ở ghép?","topic":null,"end_ms":182088,"status":"published","explore":"## Hai câu hỏi rất hay gặp\r\nKhi làm quen, người Anh hay hỏi hai câu: \"Where do you live?\" (Bạn sống ở đâu?) và \"Who do you live with?\" (Bạn sống với ai?). Khi nói nhanh, \"do you\" gần như thành \"də-jə\", nên nghe cả câu như \"Where-də-jə-live?\".\r\n\r\n## House hay flat?\r\n- **house:** một ngôi nhà riêng, thường có nhiều tầng.\r\n- **flat:** căn hộ trong một tòa nhà. Người Mỹ gọi là apartment, người Anh gọi là flat.\r\n\r\n## Sống với ai?\r\n- **with my family:** với gia đình.\r\n- **with my housemates:** với những người ở chung nhà (house).\r\n- **with my flatmates:** với những người ở chung căn hộ (flat).\r\n- **on my own:** một mình, giống \"alone\" nhưng tự nhiên hơn khi nói.\r\n\r\n## Trong video\r\nBốn người dẫn chương trình của BBC Learning English kể về nơi họ sống: Tim và Georgie ở London, Sian ở Brighton, Buli ở Cambridge. Thuê nhà ở ghép rất phổ biến với người trẻ ở Anh vì giá thuê nhà ở các thành phố lớn như London rất cao.","short_id":"f0b1ac2d","start_ms":139530,"is_premium":false,"gist_answer":2,"gist_prompt":"Ai sống một mình?","date_created":"2026-11-23T04:03:35.296989+00:00","date_updated":"2026-11-24T02:58:31.100741+00:00","gist_explain":"Buli: \"I live in a flat in Cambridge ... I live on my own.\"","gist_options":["Georgie","Sian","Buli"],"gist_sentences":[7,10],"source_video_id":"301cb966-9acb-4a62-8664-6c23ab7db265"}$sync$::jsonb) o
    where t."id" = n."id" and t."status"::text is not distinct from o."status"::text and t."date_updated"::text is not distinct from o."date_updated"::text;
  if not found and not exists (select 1 from "il_lessons" t, jsonb_populate_record(null::"il_lessons", $sync${"id":"8697a61b-9d6d-4265-98c1-565fe58f539e","note":null,"slug":"saying-where-you-live","sort":0,"focus":"linking","intro":"Ở Anh, người trẻ rất hay thuê chung nhà với bạn bè hoặc cả người lạ. Hãy nghe bốn người kể họ sống ở đâu và sống với ai.","level":1,"title":"Bạn sống một mình hay ở ghép?","topic":null,"end_ms":182088,"status":"draft","explore":"## Hai câu hỏi rất hay gặp\r\nKhi làm quen, người Anh hay hỏi hai câu: \"Where do you live?\" (Bạn sống ở đâu?) và \"Who do you live with?\" (Bạn sống với ai?). Khi nói nhanh, \"do you\" gần như thành \"də-jə\", nên nghe cả câu như \"Where-də-jə-live?\".\r\n\r\n## House hay flat?\r\n- **house:** một ngôi nhà riêng, thường có nhiều tầng.\r\n- **flat:** căn hộ trong một tòa nhà. Người Mỹ gọi là apartment, người Anh gọi là flat.\r\n\r\n## Sống với ai?\r\n- **with my family:** với gia đình.\r\n- **with my housemates:** với những người ở chung nhà (house).\r\n- **with my flatmates:** với những người ở chung căn hộ (flat).\r\n- **on my own:** một mình, giống \"alone\" nhưng tự nhiên hơn khi nói.\r\n\r\n## Trong video\r\nBốn người dẫn chương trình của BBC Learning English kể về nơi họ sống: Tim và Georgie ở London, Sian ở Brighton, Buli ở Cambridge. Thuê nhà ở ghép rất phổ biến với người trẻ ở Anh vì giá thuê nhà ở các thành phố lớn như London rất cao.","short_id":"f0b1ac2d","start_ms":139530,"is_premium":false,"gist_answer":2,"gist_prompt":"Ai sống một mình?","date_created":"2026-11-23T04:03:35.296989+00:00","date_updated":"2026-11-25T08:35:58.660869+00:00","gist_explain":"Buli: \"I live in a flat in Cambridge ... I live on my own.\"","gist_options":["Georgie","Sian","Buli"],"gist_sentences":[7,10],"source_video_id":"301cb966-9acb-4a62-8664-6c23ab7db265"}$sync$::jsonb) n where t."id" = n."id" and t."status"::text is not distinct from n."status"::text and t."date_updated"::text is not distinct from n."date_updated"::tex