insert into "il_sentences" ("id", "lesson_id", "n", "start_ms", "end_ms", "text", "traps", "sub", "key_words", "part") select "id", "lesson_id", "n", "start_ms", "end_ms", "text", "traps", "sub", "key_words", "part" from jsonb_populate_recordset(null::"il_sentences", $sync$[{"n":1,"id":"44b40490-886e-413d-a019-29d8ba0186b8","sub":null,"part":1,"text":"Don't start panicking.","traps":[{"kind":"linking","note":"Âm t cuối don't gần mất trước start, nên dễ sót ý phủ định.","real":"/dəʊn stɑːt/ (nghe như \"đâun-START\")","text":"Don't start","skill":"t-d-dropping"}],"end_ms":305520,"start_ms":303759,"key_words":["dont"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":2,"id":"09b81f26-5070-40b3-bd13-d3fd01600dfa","sub":null,"part":1,"text":"Wear those stripy legs with pride.","traps":[],"end_ms":314590,"start_ms":312400,"key_words":["pride"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":3,"id":"3f01c4fb-b0f5-4280-ab6b-01c0af7528a5","sub":null,"part":1,"text":"Knowing you still have possibilities is a luxury.","traps":[],"end_ms":317690,"start_ms":314960,"key_words":["possibilities","luxury"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":4,"id":"9e4a5ec4-3cd7-4a38-94b6-6641e9dd03c5","sub":null,"part":1,"text":"Knowing I might have given them to you has eased something for me.","traps":[{"kind":"linking","note":"Âm t trong might đọc nhẹ thành đ rồi dính vào have đọc yếu.","real":"/ˈmaɪ ɾəv/ (nghe như \"MAI-đơv\")","text":"might have","skill":"flap-t"},{"kind":"linking","note":"Âm cuối của has nối sang eased, nghe như từ sau bắt đầu bằng z.","real":"/hə ˈziːzd/ (nghe như \"hơ-ZIZD\")","text":"has eased","skill":"linking-words"}],"end_ms":322890,"start_ms":318479,"key_words":["eased"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":5,"id":"e40f9169-04ee-45dc-ac0e-fdce572c213d","sub":null,"part":1,"text":"So, this is it.","traps":[],"end_ms":326730,"start_ms":324000,"key_words":[],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":6,"id":"e313b5cb-6fbe-4c26-b4d2-6f101f0f5609","sub":null,"part":1,"text":"You are scored on my heart, Clark.","traps":[{"kind":"linking","note":"Đuôi d của scored nối sang on, dễ nghe thành score on.","real":"/ˈskɔː dɒn/ (nghe như \"sko-ĐON\")","text":"scored on","skill":"linking-words"}],"end_ms":330720,"start_ms":327600,"key_words":["scored"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":7,"id":"62e94ca5-a724-46c7-9d5b-764fc3786fc6","sub":null,"part":1,"text":"Don't think of me too often.","traps":[{"kind":"linking","note":"Âm k của think nối sang of đọc yếu.","real":"/ˈθɪŋ kəv/ (nghe như \"THING-kơv\")","text":"think of","skill":"linking-words"}],"end_ms":344430,"start_ms":342720,"key_words":["dont"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":8,"id":"db93e119-b7af-4b9a-b7e1-edcb97584c4e","sub":null,"part":1,"text":"I don't want you getting sad.","traps":[{"kind":"linking","note":"Âm t gặp you biến thành ch.","real":"/ˈwɒn tʃu/ (nghe như \"WON-chu\")","text":"want you","skill":"yod-coalescence"}],"end_ms":346710,"start_ms":345120,"key_words":["sad"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":9,"id":"16c60b24-6cf3-426a-931c-ecd8650da929","sub":null,"part":1,"text":"Just live well.","traps":[],"end_ms":348609,"start_ms":347360,"key_words":["well"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":10,"id":"ba663065-c31b-44f8-8b12-57f5f0cb2454","sub":null,"part":1,"text":"Just live.","traps":[],"end_ms":351329,"start_ms":350240,"key_words":[],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":11,"id":"59008797-5e73-4a65-9339-764af9273259","sub":null,"part":1,"text":"I'll be walking beside you every step of the way.","traps":[{"kind":"linking","note":"Âm l của I'll rất mờ trước be, dễ nghe thành I be.","real":"/aɪl bi/ (nghe như \"ao-bi\")","text":"I'll be","skill":"contractions"}],"end_ms":355510,"start_ms":353039,"key_words":["beside"],"lesson_id":"3fb72aa8-9f92-408e-b1c6-b26b71312916"},{"n":1,"id":"7836eed7-c847-426d-9a6a-8a3e0da81c07","sub":"Những mối quan hệ bạo hành không bắt đầu bằng bạo hành.","part":1,"text":"Abusive relationships don't start out abusive.","traps":[{"kind":"linking","note":"Âm t giữa hai nguyên âm đọc nhẹ thành đ, hai từ dính liền.","real":"/ˈstɑːr ɾaʊt/ (nghe như \"star-ĐAO(t)\")","text":"start out","skill":"flap-t"}],"end_ms":224058,"start_ms":221850,"key_words":["dont"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":2,"id":"4e27b715-fc93-4a7c-97c6-7df033922d00","sub":"Chúng bắt đầu đầy hào hứng và phấn khích.","part":1,"text":"They start out exciting and exhilarating.","traps":[{"kind":"linking","note":"and đọc yếu rồi nối âm n vào exhilarating.","real":"/ən ɪɡˈzɪl/ (nghe như \"ơ-nig-ZIL\")","text":"and exhilarating","skill":"linking-words"}],"end_ms":226058,"start_ms":224058,"key_words":[],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":3,"id":"ed3eca49-8136-4a24-9998-3f594d9a8059","sub":"Có sự mãnh liệt của tình cảm và cảm xúc, một cơn lâng lâng.","part":1,"text":"There's an intensity of affection and emotion, a rush.","traps":[{"kind":"linking","note":"Âm z của There's nối sang an.","real":"/ðer zən/ (nghe như \"đe-zơn\")","text":"There's an","skill":"linking-words"}],"end_ms":229392,"start_ms":226058,"key_words":["intensity"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":4,"id":"e843f306-ba7b-44ca-8483-c1636e6f0d21","sub":"Cảm giác rất tuyệt.","part":1,"text":"It feels really good.","traps":[],"end_ms":231100,"start_ms":229392,"key_words":[],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":5,"id":"b57a36f8-7846-4a62-9d17-fa3a4f07d861","sub":"Bạn thấy mình thật may mắn, như trúng số độc đắc.","part":1,"text":"You feel so lucky, like you've hit the jackpot.","traps":[],"end_ms":233667,"start_ms":231100,"key_words":["lucky"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":6,"id":"a9e80acf-acfb-46e9-8df5-b3b2b2147fa6","sub":"Bạn cảm thấy điều đó từ trong bụng.","part":1,"text":"You feel it in your gut.","traps":[{"kind":"linking","note":"Ba từ ngắn nối thành một chuỗi liền.","real":"/ˈfiː lɪ ɾɪn/ (nghe như \"FIU-li-đin\")","text":"feel it in","skill":"linking-words"}],"end_ms":244475,"start_ms":242725,"key_words":["gut"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":7,"id":"c6781404-8b5f-4081-8d2a-72b2cffb41c7","sub":"Điều quan trọng cần nhớ là: một mối quan hệ bắt đầu thế nào không quan trọng bằng nó phát triển ra sao.","part":1,"text":"It's important to remember that it's not how a relationship starts that matters, it's how it evolves.","traps":[],"end_ms":265808,"start_ms":260433,"key_words":["not","evolves"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":8,"id":"3861c54a-34e9-4898-8cdb-d508f16a29e6","sub":"Những ngày đầu của một mối quan hệ mới, việc để ý cảm giác của mình rất quan trọng.","part":1,"text":"It's important in the early days of a new relationship to pay attention to how you're feeling.","traps":[],"end_ms":270433,"start_ms":265808,"key_words":["feeling"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":9,"id":"190e9063-22e6-45a2-8106-80b739d799b9","sub":"Bạn có thoải mái với tốc độ gần gũi này không?","part":1,"text":"Are you comfortable with the pace of intimacy?","traps":[{"kind":"linking","note":"Âm s của pace nối sang of đọc yếu.","real":"/ˈpeɪ səv/ (nghe như \"PÂY-sơv\")","text":"pace of","skill":"linking-words"}],"end_ms":273058,"start_ms":270433,"key_words":["pace"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":10,"id":"972f8b47-3d29-4cb9-98f2-e4b213f0b262","sub":"Bạn có thấy mình còn không gian để thở không?","part":1,"text":"Do you feel like you have space and room to breathe?","traps":[],"end_ms":275792,"start_ms":273058,"key_words":["breathe"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":11,"id":"cee75107-3542-4479-8369-2eb3b6c3bb39","sub":"Cũng rất quan trọng là bắt đầu tập dùng tiếng nói của mình để nói về điều mình cần.","part":1,"text":"It's also really important to start practicing using your voice to talk about your own needs.","traps":[{"kind":"linking","note":"Âm k của talk nối sang about.","real":"/ˈtɔː kəˌbaʊt/ (nghe như \"TO-kơ-BAO(t)\")","text":"talk about","skill":"linking-words"}],"end_ms":282267,"start_ms":276642,"key_words":["needs"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":12,"id":"e3900f92-d41d-454c-a431-5f8f4dedf526","sub":"Những đề nghị của bạn có được tôn trọng không?","part":1,"text":"Are your requests respected?","traps":[{"kind":"imagine","note":"Âm t kẹt giữa hai âm s nên gần mất, khó nghe đuôi số nhiều.","real":"/rɪˈkwes(t)s/ (nghe như \"ri-KWES\")","text":"requests","skill":"t-d-dropping"}],"end_ms":284333,"start_ms":282267,"key_words":["respected"],"lesson_id":"d15579dc-1aca-4883-a327-b1e083d437e1"},{"n":1,"id":"07a990aa-9717-4eeb-a7fb-db88129f19a7","sub":"Bạn thậm chí có thể đứng ở một tư thế đầy sức mạnh hoặc tự nói lời động viên.","part":1,"text":"You can even strike a powerful pose or give yourself a pep talk.","traps":[{"kind":"linking","note":"Âm f cuối yourself nối sang a.","real":"/jərˈsel fə/ (nghe như \"jơ-SEL-fơ\")","text":"yourself a","skill":"linking-words"}],"end_ms":118404,"start_ms":113396,"key_words":["pose"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":2,"id":"ffeea033-398c-40ec-9d3a-70455ecbba4a","sub":"Mẹo thứ hai: tin vào khả năng tiến bộ của mình.","part":1,"text":"Tip two: believe in your ability to improve.","traps":[{"kind":"linking","note":"Âm v của believe nối sang in.","real":"/bɪˈliː vɪn/ (nghe như \"bơ-LI-vin\")","text":"believe in","skill":"linking-words"}],"end_ms":123674,"start_ms":118404,"key_words":["improve"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":3,"id":"a2223d4a-2ada-4161-bb28-3ca72bfa1611","sub":"Nếu bạn muốn thay đổi lâu dài, hãy xem lại cách mình nghĩ về năng lực và tài năng của bản thân.","part":1,"text":"If you're looking for a long-term change, consider the way you think about your abilities and talents.","traps":[{"kind":"linking","note":"Âm k của think nối sang about.","real":"/ˈθɪŋ kəˌbaʊt/ (nghe như \"THING-kơ-BAO(t)\")","text":"think about","skill":"linking-words"}],"end_ms":129745,"start_ms":123674,"key_words":[],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":4,"id":"d77bed81-ff5c-4cba-871f-2429067a1c25","sub":"Bạn nghĩ chúng cố định từ khi sinh ra, hay có thể rèn được, giống như cơ bắp?","part":1,"text":"Do you think they are fixed at birth, or that they can be developed, like a muscle?","traps":[{"kind":"linking","note":"Đuôi t của fixed nối sang at, dễ sót quá khứ phân từ.","real":"/ˈfɪk stət/ (nghe như \"FIK-stơt\")","text":"fixed at","skill":"linking-words"}],"end_ms":134950,"start_ms":129745,"key_words":["fixed","developed"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":5,"id":"143d56ae-625b-4866-a4e6-88ceb015babb","sub":"Những niềm tin này quan trọng vì chúng ảnh hưởng đến cách bạn hành động khi gặp trở ngại.","part":1,"text":"These beliefs matter because they can influence how you act when you're faced with setbacks.","traps":[{"kind":"linking","note":"Đuôi ed đứng trước w gần như mất.","real":"/ˈfeɪs(t) wɪð/ (nghe như \"FÂYS-with\")","text":"faced with","skill":"ed-endings"}],"end_ms":140444,"start_ms":134950,"key_words":["influence"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":6,"id":"0044b3c3-7f77-416b-99d2-3d1365d6d90e","sub":"Khoa học thần kinh ủng hộ tư duy phát triển.","part":1,"text":"Neuroscience supports the growth mindset.","traps":[],"end_ms":160671,"start_ms":158193,"key_words":["supports"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":7,"id":"fbd215ba-7002-48ee-b829-b408cd46d50b","sub":"Các kết nối trong não bạn thật sự mạnh lên và phát triển khi học và luyện tập.","part":1,"text":"The connections in your brain do get stronger and grow with study and practice.","traps":[],"end_ms":165878,"start_ms":160671,"key_words":["stronger"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":8,"id":"58b9554c-b684-432a-8d2b-1f75723d9a88","sub":"Mẹo thứ ba: tập thất bại.","part":1,"text":"Tip three: practice failure.","traps":[],"end_ms":179601,"start_ms":176379,"key_words":["failure"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":9,"id":"12f2926d-bafa-4b7e-a36d-87d52b9befb1","sub":"Chấp nhận đi, thỉnh thoảng bạn sẽ thất bại.","part":1,"text":"Face it, you're going to fail sometimes.","traps":[{"kind":"linking","note":"Âm s của Face nối sang it thành một tiếng liền.","real":"/ˈfeɪ sɪt/ (nghe như \"FÂY-sit\")","text":"Face it","skill":"linking-words"}],"end_ms":182256,"start_ms":179601,"key_words":["fail"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"},{"n":10,"id":"92050805-13a8-401d-91c2-3d59bc3d99cf","sub":"Ai cũng vậy.","part":1,"text":"Everyone does.","traps":[],"end_ms":183606,"start_ms":182256,"key_words":["everyone"],"lesson_id":"bfd37ff0-5b16-4600-81ce-3fada909932d"}]$sync$::jsonb) on conflict do nothing;
