    from jsonb_populate_record(null::"il_sentences", $sync${"n":10,"id":"c199cf15-0174-4c1a-8e26-85a0bb295337","sub":"Hay rời khỏi một người không làm ta thỏa mãn?","part":1,"text":"Or move on from an unsatisfying person?","traps":[{"kind":"linking","note":"v của move dính sang on; from an dính thành \"frơ-mơn\".","real":"/muːˈvɒn frəmən/ (nghe như \"mu-VON-frơ-mơn\")","text":"move on from an","skill":"linking-words"}],"end_ms":259400,"start_ms":256900,"key_words":["unsatisfying"],"lesson_id":"a9f2f481-b123-4144-b020-cbe8b79f1aaa"}$sync$::jsonb) n, jsonb_populate_record(null::"il_sentences", $sync${"n":10,"id":"c199cf15-0174-4c1a-8e26-85a0bb295337","sub":"Hay rời khỏi một người không làm ta thỏa mãn?","part":1,"text":"Or move on from an unsatisfying one?","traps":[{"kind":"linking","note":"v của move dính sang on; from an dính thành \"frơ-mơn\".","real":"/muːˈvɒn frəmən/ (nghe như \"mu-VON-frơ-mơn\")","text":"move on from an","skill":"linking-words"}],"end_ms":259429,"start_ms":256929,"key_words":["unsatisfying"],"lesson_id":"a9f2f481-b123-4144-b020-cbe8b79f1aaa"}$sync$::jsonb) o
