  if not found and not exists (select 1 from "il_sentences" t, jsonb_populate_record(null::"il_sentences", $sync${"n":10,"id":"c199cf15-0174-4c1a-8e26-85a0bb295337","sub":"Hay rời khỏi một người không làm ta thỏa mãn?","part":1,"text":"Or move on from an unsatisfying person?","traps":[{"kind":"linking","note":"v của move dính sang on; from an dính thành \"frơ-mơn\".","real":"/muːˈvɒn frəmən/ (nghe như \"mu-VON-frơ-mơn\")","text":"move on from an","skill":"linking-words"}],"end_ms":259400,"start_ms":256900,"key_words":["unsatisfying"],"lesson_id":"a9f2f481-b123-4144-b020-cbe8b79f1aaa"}$sync$::jsonb) n where t."id" = n."id" and t."start_ms"::text is not distinct from n."start_ms"::text and t."end_ms"::text is not distinct from n."end_ms"::text and t."text"::text is not distinct from n."text"::text) then
