":"phrase","term":"crack a bullwhip","forms":[],"meaning":"quất roi cho kêu","lesson_id":"6c2ca5b3-2cff-47a3-bc88-c473c95d20dd","sentence_n":3,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"e10b374e-7e20-4b1b-891d-0dd3da075fdb","kind":"phrase","term":"capable of","forms":[],"meaning":"có khả năng","lesson_id":"6c2ca5b3-2cff-47a3-bc88-c473c95d20dd","sentence_n":4,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"930f17b9-6f0a-454a-9914-05c7a0b9ee79","kind":"word","term":"stun","forms":["stuns","stunned"],"meaning":"làm choáng","lesson_id":"6c2ca5b3-2cff-47a3-bc88-c473c95d20dd","sentence_n":7,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"f4dd23aa-f72e-4b80-8f19-95b52026a7ce","kind":"grammar","term":"by clapping your hands","forms":[],"meaning":"bằng cách vỗ tay (by + V-ing)","lesson_id":"6c2ca5b3-2cff-47a3-bc88-c473c95d20dd","sentence_n":8,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"0005bb53-b67b-49a2-b557-19f46df74cc4","kind":"phrase","term":"For goodness sake","forms":[],"meaning":"trời đất ơi","lesson_id":"6c2ca5b3-2cff-47a3-bc88-c473c95d20dd","sentence_n":9,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"29c29e99-3985-4c44-a937-e6b76c5d7d3e","kind":"phrase","term":"ridiculous amount of","forms":[],"meaning":"một lượng vô lý","lesson_id":"6c2ca5b3-2cff-47a3-bc88-c473c95d20dd","sentence_n":10,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"44be011f-3b4c-4687-8a59-6672968ec0e2","kind":"word","term":"emerge","forms":["emerges","emerged"],"meaning":"xuất hiện, nảy sinh","lesson_id":"d80529c6-8c2d-48bd-82bd-bf1ee98ea26c","sentence_n":2,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"579ed98f-ea55-4b0f-8605-3204a057dd2f","kind":"word","term":"handle","forms":["handles"],"meaning":"xử lý","lesson_id":"d80529c6-8c2d-48bd-82bd-bf1ee98ea26c","sentence_n":3,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"f1c2a760-63fa-4a85-a44d-0b1ee38514ed","kind":"word","term":"complexity","forms":[],"meaning":"độ phức tạp","lesson_id":"d80529c6-8c2d-48bd-82bd-bf1ee98ea26c","sentence_n":5,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"53067842-4769-40b3-b9c2-0710cf08b2a6","kind":"grammar","term":"more than the sum of their parts","forms":[],"meaning":"hơn tổng các phần cộng lại","lesson_id":"d80529c6-8c2d-48bd-82bd-bf1ee98ea26c","sentence_n":6,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"5f9b4859-30d5-4d95-9e15-d17710566eb2","kind":"phrase","term":"breaks down","forms":["break down"],"meaning":"không còn đúng nữa","lesson_id":"d80529c6-8c2d-48bd-82bd-bf1ee98ea26c","sentence_n":7,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"49100ab5-6077-484f-9e50-8020d0e4f0d3","kind":"phrase","term":"make sense","forms":["makes sense"],"meaning":"có ý nghĩa, hiểu được","lesson_id":"d80529c6-8c2d-48bd-82bd-bf1ee98ea26c","sentence_n":8,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"78231c5b-4d32-4230-8c31-2bcf42a9d734","kind":"phrase","term":"the whole story","forms":[],"meaning":"toàn bộ câu chuyện","lesson_id":"d80529c6-8c2d-48bd-82bd-bf1ee98ea26c","sentence_n":12,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"04777a2b-4fa2-4c7f-af16-23a4bea5ab9a","kind":"word","term":"increasingly","forms":[],"meaning":"ngày càng","lesson_id":"77ddd63c-d225-47fa-bbf0-d1c50321b715","sentence_n":1,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"c988a0f2-b417-4d6b-9e65-bec70c40c749","kind":"phrase","term":"sweat glands","forms":["sweat gland"],"meaning":"tuyến mồ hôi","lesson_id":"77ddd63c-d225-47fa-bbf0-d1c50321b715","sentence_n":2,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"6a7de368-961c-42b1-8d9e-c9d71c47c431","kind":"word","term":"moisture","forms":[],"meaning":"hơi ẩm","lesson_id":"77ddd63c-d225-47fa-bbf0-d1c50321b715","sentence_n":2,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"10bbb555-fb79-451c-b99d-96b68f08ae11","kind":"word","term":"advantageous","forms":[],"meaning":"có lợi","lesson_id":"77ddd63c-d225-47fa-bbf0-d1c50321b715","sentence_n":4,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"9cfd0665-1fe6-44af-90a2-ab69eadd0376","kind":"phrase","term":"at all","forms":[],"meaning":"chút nào","lesson_id":"77ddd63c-d225-47fa-bbf0-d1c50321b715","sentence_n":4,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"010e115a-0767-486b-87f6-0e7c479ac2ae","kind":"grammar","term":"When it comes to","forms":[],"meaning":"còn nói về","lesson_id":"77ddd63c-d225-47fa-bbf0-d1c50321b715","sentence_n":6,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"94e7528d-079b-426e-831c-1f671bb7b3ab","kind":"phrase","term":"played a part","forms":["play a part"],"meaning":"góp phần","lesson_id":"77ddd63c-d225-47fa-bbf0-d1c50321b715","sentence_n":6,"date_created":"2026-11-25T10:05:14.112759+00:00"},{"id":"97625ca5-df7e-4f00-a48d-5fed7a4e5e8f","kind":"word","term":"scorching","forms":[],"meaning":"nóng như thiêu","lesson_id":"77ddd63c-d225-47fa-bbf0-d1c50321b715","sentence_n":7,"date_created":"2026-11-25T10:05:14.112759+00:00"}]$sync$::jsonb) on conflict do nothing;
