-- review_quotes: 542 new, 0 changed
insert into "review_quotes" ("id", "quote", "meaning", "author", "topic", "status", "date_created") select "id", "quote", "meaning", "author", "topic", "status", "date_created" from jsonb_populate_recordset(null::"review_quotes", $sync$[{"id":"c3b94afc-9bdc-435c-8ada-8c5d78fc1506","quote":"As many languages as you know, that many times you are a human being.","topic":"Học ngoại ngữ","author":"Tục ngữ Séc","status":"draft","meaning":"Bạn biết bao nhiêu ngôn ngữ, bạn là bấy nhiêu con người.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"33dc617c-b43b-4a86-a4e5-bbb2956f69e8","quote":"Learning another language is not only learning different words for the same things, but learning another way to think about things.","topic":"Học ngoại ngữ","author":"Flora Lewis","status":"draft","meaning":"Học một ngôn ngữ khác không chỉ là học những từ khác nhau cho cùng một sự vật, mà là học một cách khác để nghĩ về sự vật.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"840858ea-8dbe-472c-af33-304115b849ef","quote":"You can never understand one language until you understand at least two.","topic":"Học ngoại ngữ","author":"Geoffrey Willans","status":"draft","meaning":"Bạn không bao giờ hiểu được một ngôn ngữ cho đến khi hiểu ít nhất hai ngôn ngữ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e7b73e08-bd95-4e7a-a6a1-e244149f83dd","quote":"Knowledge of languages is the doorway to wisdom.","topic":"Học ngoại ngữ","author":"Roger Bacon","status":"draft","meaning":"Hiểu biết ngôn ngữ là cánh cửa dẫn đến trí tuệ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0a31ed22-8092-42c9-ab47-e10af23ffe6e","quote":"The conquest of learning is achieved through the knowledge of languages.","topic":"Học ngoại ngữ","author":"Roger Bacon","status":"approved","meaning":"Chinh phục tri thức bắt đầu từ việc thông hiểu ngôn ngữ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f96b01dc-eba8-4fa6-8405-e6b1d03be177","quote":"We should learn languages because language is the only thing worth knowing even poorly.","topic":"Học ngoại ngữ","author":"Kató Lomb","status":"draft","meaning":"Ta nên học ngoại ngữ, vì ngôn ngữ là thứ duy nhất đáng để biết, dù chỉ biết sơ sài.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3825905e-1a6a-4fb4-aa7a-583d88c478d9","quote":"Learning another language is like becoming another person.","topic":"Học ngoại ngữ","author":"Haruki Murakami","status":"draft","meaning":"Học một ngôn ngữ khác giống như trở thành một con người khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"feb58eb4-1d88-4973-bec2-ba08de76efca","quote":"One language, one person; two languages, two people.","topic":"Học ngoại ngữ","author":"Tục ngữ Thổ Nhĩ Kỳ","status":"draft","meaning":"Biết một ngôn ngữ là một con người, biết hai ngôn ngữ là hai con người.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9e67cb28-8346-4867-9ed2-008f752bf98e","quote":"Learn a new language and get a new soul.","topic":"Học ngoại ngữ","author":"Tục ngữ Séc","status":"draft","meaning":"Học một ngôn ngữ mới, có thêm một tâm hồn mới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5db278f2-c54b-4a92-86b2-824310064c84","quote":"Language is to the mind more than light is to the eye.","topic":"Học ngoại ngữ","author":"William Gibson","status":"draft","meaning":"Ngôn ngữ với tâm trí còn quan trọng hơn ánh sáng với đôi mắt.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3324ae90-852b-431f-a315-2d3e5ff09a60","quote":"Do you know what a foreign accent is? It's a sign of bravery.","topic":"Học ngoại ngữ","author":"Amy Chua","status":"draft","meaning":"Bạn có biết giọng nước ngoài là gì không? Đó là dấu hiệu của lòng can đảm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"44b9c485-1eb2-4c29-828e-da42aaca1ee1","quote":"Change your language and you change your thoughts.","topic":"Học ngoại ngữ","author":"Karl Albrecht","status":"draft","meaning":"Thay đổi ngôn ngữ, bạn sẽ thay đổi suy nghĩ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f489b457-9f66-428e-8279-022697ff24bd","quote":"With languages, you are at home anywhere.","topic":"Học ngoại ngữ","author":"Edmund de Waal","status":"draft","meaning":"Có ngôn ngữ, ở đâu bạn cũng như ở nhà.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ceef8ebf-4ae1-43aa-b051-471884276ab6","quote":"The joy of knowing a foreign language is inexpressible. I find it really difficult to express such joy in my mother tongue.","topic":"Học ngoại ngữ","author":"Munia Khan","status":"draft","meaning":"Niềm vui khi biết một ngoại ngữ thật không tả xiết. Tôi thấy thật khó diễn tả niềm vui ấy bằng chính tiếng mẹ đẻ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"747d5605-fd92-4caa-8dad-40192d09770c","quote":"I love commuting between languages just like I love commuting between cultures and cities.","topic":"Học ngoại ngữ","author":"Elif Şafak","status":"draft","meaning":"Tôi thích đi lại giữa các ngôn ngữ như thích đi lại giữa các nền văn hóa và thành phố.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cb0fee5a-e130-40af-bce1-738ef60b64f4","quote":"A special kind of beauty exists which is born in language, of language, and for language.","topic":"Học ngoại ngữ","author":"Gaston Bachelard","status":"draft","meaning":"Có một vẻ đẹp đặc biệt sinh ra trong ngôn ngữ, từ ngôn ngữ và vì ngôn ngữ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"52d83188-6220-463f-bec3-d7ccd4fb1034","quote":"Speak a new language so that the world will be a new world.","topic":"Học ngoại ngữ","author":"Rumi","status":"draft","meaning":"Hãy nói một ngôn ngữ mới để thế giới trở thành một thế giới mới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ff5239c6-af7c-4c99-aa44-020915babdbf","quote":"A new language is a new life.","topic":"Học ngoại ngữ","author":"Tục ngữ Ba Tư","status":"draft","meaning":"Một ngôn ngữ mới là một cuộc đời mới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"656dc64a-cccb-4fb6-9a00-1c7f069dd647","quote":"We have strong evidence today that studying a foreign language has a ripple effect, helping to improve student performance in other subjects.","topic":"Học ngoại ngữ","author":"Richard Riley","status":"draft","meaning":"Ngày nay có bằng chứng rõ ràng rằng học ngoại ngữ tạo hiệu ứng lan tỏa, giúp học sinh học tốt hơn cả các môn khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9c303769-b5a4-4d1d-a96f-60f0988d377a","quote":"We invent the world through language. The world occurs through language.","topic":"Học ngoại ngữ","author":"Mal Pancoast","status":"draft","meaning":"Ta tạo nên thế giới qua ngôn ngữ. Thế giới hiện ra qua ngôn ngữ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b5cc75fe-3623-4cd5-8510-423cf73f9e9a","quote":"A language is an exact reflection of the character and growth of its speakers.","topic":"Học ngoại ngữ","author":"César Chávez","status":"draft","meaning":"Ngôn ngữ phản chiếu chính xác tính cách và sự trưởng thành của những người nói nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"df1ba1d5-4f0a-4f25-900a-691fe86fd1c2","quote":"Any time you think some other language is strange, remember that yours is just as strange, you're just used to it.","topic":"Học ngoại ngữ","author":"Khuyết danh","status":"draft","meaning":"Mỗi khi thấy ngôn ngữ khác lạ lùng, hãy nhớ rằng ngôn ngữ của bạn cũng lạ y như vậy, chỉ là bạn đã quen.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"acd06fab-b313-4d95-84d7-73827d4b154e","quote":"Language exerts hidden power, like a moon on the tides.","topic":"Học ngoại ngữ","author":"Rita Mae Brown","status":"draft","meaning":"Ngôn ngữ có một sức mạnh ngầm, như mặt trăng với thủy triều.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"73e50a00-7e84-44f3-948b-ba0112e75704","quote":"If we spoke a different language, we would perceive a somewhat different world.","topic":"Học ngoại ngữ","author":"Ludwig Wittgenstein","status":"draft","meaning":"Nếu nói một ngôn ngữ khác, ta sẽ cảm nhận một thế giới có phần khác đi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c81f8703-cc88-4d3a-8072-ec0317fe7948","quote":"Language shapes the way we think, and determines what we can think about.","topic":"Học ngoại ngữ","author":"Benjamin Lee Whorf","status":"draft","meaning":"Ngôn ngữ định hình cách ta suy nghĩ, và quyết định những gì ta có thể nghĩ đến.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"28f9f36d-9f98-4dea-8160-41186837bc6c","quote":"Whoever learns a people's language is safe from their cunning.","topic":"Học ngoại ngữ","author":"Châm ngôn Ả Rập","status":"draft","meaning":"Ai học được ngôn ngữ của một dân tộc sẽ tránh được mưu kế của họ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"682bffc6-8fe2-4891-9606-d5d889267551","quote":"The most intimate temper of a people, its deepest soul, is above all in its language.","topic":"Học ngoại ngữ","author":"Jules Michelet","status":"draft","meaning":"Tính khí sâu kín nhất, tâm hồn thẳm sâu nhất của một dân tộc, trước hết nằm trong ngôn ngữ của họ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"764acc43-0b2b-4190-b0dd-d6065dc85cc3","quote":"The soul of a people is reflected in its language.","topic":"Học ngoại ngữ","author":"Paul Schibler","status":"draft","meaning":"Tâm hồn của một dân tộc phản chiếu trong ngôn ngữ của họ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7b930289-14f1-433d-92c1-1c5da84c52ed","quote":"I was beginning to think in Greek. That is the great Rubicon to cross in learning any language.","topic":"Học ngoại ngữ","author":"C. S. Lewis","status":"draft","meaning":"Tôi đã bắt đầu nghĩ bằng tiếng Hy Lạp. Đó là dòng sông Rubicon lớn phải vượt qua khi học bất kỳ ngôn ngữ nào.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d579da51-2665-4f5e-b8bf-c2aae49ae70a","quote":"Invested time × Motivation ÷ Inhibition = Result.","topic":"Học ngoại ngữ","author":"Kató Lomb","status":"draft","meaning":"Thời gian đầu tư × Động lực ÷ Sự e ngại = Kết quả.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d849c6f9-a7bd-4208-a7db-d5da26f0d641","quote":"We die. That may be the meaning of life. But we do language. That may be the measure of our lives.","topic":"Học ngoại ngữ","author":"Toni Morrison","status":"draft","meaning":"Chúng ta chết. Đó có thể là ý nghĩa của sự sống. Nhưng chúng ta làm nên ngôn ngữ. Đó có thể là thước đo cuộc đời ta.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0aa0e610-9e3e-4d10-a146-fb75cba5a937","quote":"He that is acquainted with only one language will probably always remain in some degree the slave of language.","topic":"Học ngoại ngữ","author":"William Godwin","status":"draft","meaning":"Người chỉ biết một ngôn ngữ có lẽ sẽ mãi ở một mức độ nào đó là nô lệ của ngôn ngữ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cdb8b05b-fb37-4254-83aa-1d7b383e6c08","quote":"Every word is a bird we teach to sing.","topic":"Học ngoại ngữ","author":"Daniel Tammet","status":"draft","meaning":"Mỗi từ ngữ là một chú chim ta dạy cho biết hót.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e6e1a8ee-b83d-4735-a7ba-719469a7e03b","quote":"I have learned more languages since the age of 60 than prior to the age of 60.","topic":"Học ngoại ngữ","author":"Steve Kaufmann","status":"draft","meaning":"Từ sau tuổi 60, tôi học được nhiều ngôn ngữ hơn cả trước tuổi 60.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1bf12e2b-464d-4666-a559-f01afe88eab0","quote":"There is no such thing as an ugly accent. Saying there is, is like saying there's an ugly flower.","topic":"Học ngoại ngữ","author":"David Crystal","status":"draft","meaning":"Không có giọng nói nào xấu cả. Nói có giọng xấu cũng giống như nói có bông hoa xấu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"49153c2d-9437-4cf8-bffb-d98bb1c3fb2c","quote":"Aim to make at least 200 mistakes a day. The more mistakes you make, the faster you become a confident language learner.","topic":"Học ngoại ngữ","author":"Benny Lewis","status":"draft","meaning":"Hãy đặt mục tiêu mắc ít nhất 200 lỗi mỗi ngày. Càng sai nhiều, bạn càng nhanh trở thành người học ngoại ngữ tự tin.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"16120f94-843a-4047-ac9f-da6709e4a2e3","quote":"We acquire language in only one way: by understanding messages, or obtaining comprehensible input.","topic":"Học ngoại ngữ","author":"Stephen Krashen","status":"draft","meaning":"Ta tiếp thu ngôn ngữ theo một cách duy nhất: bằng cách hiểu thông điệp, tức là nhận được đầu vào có thể hiểu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"960cd214-1de3-4720-8451-90afaed134d1","quote":"Language is best taught when it is being used to transmit messages, not when it is explicitly taught for conscious learning.","topic":"Học ngoại ngữ","author":"Stephen Krashen","status":"draft","meaning":"Ngôn ngữ được dạy tốt nhất khi nó được dùng để truyền tải thông điệp, chứ không phải khi được dạy tường minh để học thuộc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"44b15d54-de6e-4d5a-9360-6b73058d55e0","quote":"Language tethers us to the world; without it we spin like atoms.","topic":"Học ngoại ngữ","author":"Penelope Lively","status":"draft","meaning":"Ngôn ngữ neo ta vào thế giới; thiếu nó, ta trôi xoay như những hạt nguyên tử.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"edf422f5-c17a-40a3-b82b-8fd78021865e","quote":"Language is the only homeland.","topic":"Học ngoại ngữ","author":"Czesław Miłosz","status":"draft","meaning":"Ngôn ngữ là quê hương duy nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"524a14b9-2e02-439a-ae47-e4aeb047964e","quote":"If I'm selling to you, I speak your language. If I'm buying, then you must speak German.","topic":"Học ngoại ngữ","author":"Willy Brandt","status":"draft","meaning":"Khi tôi bán hàng cho bạn, tôi nói ngôn ngữ của bạn. Khi tôi mua, thì bạn phải nói tiếng Đức.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"291f3976-99c3-47eb-9fdc-4b1e8050de0c","quote":"Our language is also our history.","topic":"Học ngoại ngữ","author":"Jacob Grimm","status":"draft","meaning":"Ngôn ngữ của chúng ta cũng chính là lịch sử của chúng ta.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6f9a362a-2a5c-4069-a9f4-48a466e3839c","quote":"It is astonishing how much enjoyment one can get out of a language that one understands imperfectly.","topic":"Học ngoại ngữ","author":"Basil Lanneau Gildersleeve","status":"draft","meaning":"Thật đáng ngạc nhiên khi ta có thể tận hưởng nhiều đến thế một ngôn ngữ mà mình chỉ hiểu chưa trọn vẹn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9693c0d9-53e7-4e94-8602-ccb041b3f0b4","quote":"Without translation, we would be living in provinces bordering on silence.","topic":"Học ngoại ngữ","author":"George Steiner","status":"draft","meaning":"Không có dịch thuật, ta sẽ sống trong những vùng đất giáp ranh với sự im lặng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e10b80e7-360e-4639-a4d6-fe286afdf7b6","quote":"Be like water, my friend.","topic":"Thành công & Hành động","author":"Bruce Lee","status":"draft","meaning":"Hãy như nước, bạn tôi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"faa8a2ce-4d97-4df7-be0a-55cfd4065356","quote":"Absolutely nothing is so important for a nation's culture as its language.","topic":"Học ngoại ngữ","author":"Wilhelm von Humboldt","status":"draft","meaning":"Không gì quan trọng với văn hóa một dân tộc bằng ngôn ngữ của họ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c6782f11-eb1c-4233-85a8-bff74a61605b","quote":"If you want people to understand you, speak their language.","topic":"Học ngoại ngữ","author":"Tục ngữ châu Phi","status":"draft","meaning":"Muốn người khác hiểu mình, hãy nói ngôn ngữ của họ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8bdd92ce-65ba-4004-8b2a-2879c5426897","quote":"You are as many a person as languages you know.","topic":"Học ngoại ngữ","author":"Tục ngữ Armenia","status":"draft","meaning":"Bạn biết bao nhiêu ngôn ngữ thì bạn là bấy nhiêu con người.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1550949d-7a39-4521-a3f5-eaf0b71ceed3","quote":"A foreign language is more easily learned in the kitchen than at school.","topic":"Học ngoại ngữ","author":"Tục ngữ Đức","status":"draft","meaning":"Ngoại ngữ học trong bếp còn dễ hơn học ở trường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ef762e1a-4b4b-4886-a2a4-eb3b73ed9a45","quote":"A man can be recognized by his language.","topic":"Học ngoại ngữ","author":"Tục ngữ Do Thái","status":"draft","meaning":"Nghe cách một người nói là biết người đó là ai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f10ce5a4-33a3-442c-b24d-76082776a014","quote":"Language is the means of getting an idea from my brain into yours without surgery.","topic":"Học ngoại ngữ","author":"Mark Amidon","status":"draft","meaning":"Ngôn ngữ là cách đưa một ý tưởng từ não tôi sang não bạn mà không cần phẫu thuật.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"aacf850e-61d2-4934-8917-9e86a7e4e9d6","quote":"Think like a wise man but communicate in the language of the people.","topic":"Học ngoại ngữ","author":"William Butler Yeats","status":"draft","meaning":"Hãy nghĩ như người thông thái nhưng nói bằng ngôn ngữ của người bình dân.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"63bb184e-3087-49fc-b34d-7e30b40ab32f","quote":"One does not inhabit a country; one inhabits a language. That is our homeland, and nothing else.","topic":"Học ngoại ngữ","author":"Emil Cioran","status":"draft","meaning":"Ta không sống trong một đất nước, ta sống trong một ngôn ngữ. Quê hương là thế, chẳng gì khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c57e236c-5c3a-4852-bfde-767f42fdc357","quote":"He who speaks a bit of a foreign language has more delight in it than he who speaks it well. Pleasure goes with superficial knowledge.","topic":"Học ngoại ngữ","author":"Friedrich Nietzsche","status":"draft","meaning":"Người biết chút ít một ngoại ngữ thích thú với nó hơn người nói giỏi. Niềm vui đi cùng sự hiểu biết hời hợt.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3e7a04e5-3d38-44ed-8040-c94231856566","quote":"Life is a foreign language; all men mispronounce it.","topic":"Học ngoại ngữ","author":"Christopher Morley","status":"draft","meaning":"Cuộc đời là một ngoại ngữ; ai cũng phát âm sai nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"bcafe1ef-ab38-4311-9374-fbe8fda50879","quote":"Usage is the best language teacher.","topic":"Học ngoại ngữ","author":"Quintilian","status":"approved","meaning":"Thói quen sử dụng là người thầy ngôn ngữ tốt nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6eeaf63b-1038-491c-9150-a962e7df75c5","quote":"I am always doing that which I cannot do, in order that I may learn how to do it.","topic":"Học ngoại ngữ","author":"Pablo Picasso","status":"draft","meaning":"Tôi luôn làm những điều mình chưa làm được, để học cách làm được chúng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cf34b68c-3054-4887-85f4-8b0bd5aeec3a","quote":"Man is man only through language.","topic":"Học ngoại ngữ","author":"Johann Gottfried Herder","status":"draft","meaning":"Con người chỉ thành người nhờ ngôn ngữ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"80e86016-6137-4318-98f6-c1927ccf1d71","quote":"Whoever learns a foreign language tips their hat to another nation.","topic":"Học ngoại ngữ","author":"Martin Kessel","status":"draft","meaning":"Ai học một ngoại ngữ là đang ngả mũ chào một dân tộc khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4a40c8c0-cc23-41ed-b9b0-13c1abfd263f","quote":"Every new language is like an open window that shows a new view of the world and broadens your outlook on life.","topic":"Học ngoại ngữ","author":"Frank Harris","status":"draft","meaning":"Mỗi ngôn ngữ mới như một cánh cửa sổ mở ra góc nhìn mới về thế giới và mở rộng quan niệm sống.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"702df52a-32fb-44a8-bf72-e43701b26d66","quote":"The difficulty of a language is inversely proportional to the motivation to learn it.","topic":"Học ngoại ngữ","author":"Reg Hindley","status":"draft","meaning":"Độ khó của một ngôn ngữ tỉ lệ nghịch với động lực học nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"eaca5de7-fca4-45e3-a72e-744a1f0afc72","quote":"Everything becomes a little different as soon as it is spoken out loud.","topic":"Học ngoại ngữ","author":"Hermann Hesse","status":"draft","meaning":"Mọi thứ đều trở nên khác đi một chút ngay khi được nói thành lời.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3709015c-91f4-4de4-a005-52ec56e9ffb0","quote":"As soon as you speak a foreign language, your facial expressions, your hands, your body language change.","topic":"Học ngoại ngữ","author":"Isabelle Adjani","status":"draft","meaning":"Ngay khi nói một ngoại ngữ, nét mặt, đôi tay và ngôn ngữ cơ thể của ta cũng thay đổi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"472bc675-6050-44ed-b586-2d338e2f3220","quote":"The French think they speak French well because they don't speak any foreign language.","topic":"Học ngoại ngữ","author":"Tristan Bernard","status":"draft","meaning":"Người Pháp tưởng mình nói tiếng Pháp giỏi vì họ chẳng nói ngoại ngữ nào.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cbc68590-f8c9-42d2-8b34-1d20ad35a726","quote":"With hard work, learning English, and getting involved, there is no limit on what you can achieve.","topic":"Học ngoại ngữ","author":"Arnold Schwarzenegger","status":"draft","meaning":"Với sự chăm chỉ, học tiếng Anh và dấn thân, không có giới hạn nào cho những gì bạn có thể đạt được.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b4de15cc-f2b4-4213-b60b-00635680ea1d","quote":"I know grammar by ear only, not by note, not by the rules.","topic":"Học ngoại ngữ","author":"Mark Twain","status":"draft","meaning":"Tôi biết ngữ pháp chỉ bằng tai, không bằng nốt nhạc, không bằng quy tắc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f2c6dec1-f747-4fbe-a239-ba513883ac03","quote":"What does it matter if you can speak two or more languages if you have nothing original to say in any language?","topic":"Học ngoại ngữ","author":"Jarod Kintz","status":"draft","meaning":"Nói được hai hay nhiều ngôn ngữ thì có ích gì nếu bạn chẳng có điều gì độc đáo để nói bằng bất kỳ ngôn ngữ nào?","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2ae37f6a-dbe8-4367-a0aa-478b7b0710fe","quote":"Broken Irish is better than clever English.","topic":"Học ngoại ngữ","author":"Tục ngữ Ireland","status":"approved","meaning":"Tiếng Ireland bập bẹ còn hơn tiếng Anh khéo léo.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"bccd994d-467a-457b-90f5-e08333a6629a","quote":"Advance step by step in the proper order.","topic":"Học ngoại ngữ","author":"Thành ngữ Trung Hoa","status":"approved","meaning":"Tuần tự nhi tiến, từng bước một theo đúng trình tự.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"88544609-5d17-438f-b350-76cc431a2a3b","quote":"Even a wise person, after a thousand considerations, will make one mistake.","topic":"Học ngoại ngữ","author":"Sử Ký","status":"approved","meaning":"Người khôn nghĩ nghìn điều, ắt có một điều sai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5102e52c-790a-4fd9-95db-6bc8adb1c527","quote":"Learning languages isn't about being smart, it's about being tenacious.","topic":"Học ngoại ngữ","author":"Khuyết danh","status":"draft","meaning":"Học ngoại ngữ không phải là chuyện thông minh, mà là chuyện bền bỉ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e46e1c87-484e-4681-af41-f8dd2e04621a","quote":"Some translators turn an author's words from gold to stone, others from stone to gold.","topic":"Học ngoại ngữ","author":"Terri Guillemets","status":"draft","meaning":"Có người dịch biến lời tác giả từ vàng thành đá, có người biến đá thành vàng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8df7ee30-c7a2-4aec-a605-f6133007ea45","quote":"Each time a language dies, another flame goes out, another sound goes silent.","topic":"Học ngoại ngữ","author":"Ariel Sabar","status":"draft","meaning":"Mỗi lần một ngôn ngữ mất đi, lại một ngọn lửa tắt, lại một âm thanh lặng im.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a7003b71-2476-49fe-b164-e903b8048365","quote":"One must not be shy where language is concerned.","topic":"Học ngoại ngữ","author":"Ann Patchett","status":"draft","meaning":"Đã là chuyện ngôn ngữ thì đừng ngại ngùng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a0bd20a6-a0a4-46f1-8dab-daa8c2144598","quote":"Being able to read a book in another language is a source of ego-stroking pride.","topic":"Học ngoại ngữ","author":"Emily O'Beirne","status":"draft","meaning":"Đọc được một cuốn sách bằng ngôn ngữ khác là niềm tự hào khiến ta thấy mình thật giỏi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7ce89919-2e27-457b-91e4-8611bc45fc79","quote":"Grammar is the breathing power for the life of language.","topic":"Học ngoại ngữ","author":"Munia Khan","status":"draft","meaning":"Ngữ pháp là hơi thở cho sự sống của ngôn ngữ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"299c93e4-1dd7-4fa1-b94c-a2862ddd2bcf","quote":"To handle a language skilfully is to practice a kind of evocative sorcery.","topic":"Học ngoại ngữ","author":"Charles Baudelaire","status":"draft","meaning":"Sử dụng ngôn ngữ một cách khéo léo là thực hành một kiểu phù thủy gợi cảm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"757ae861-6160-4b1b-b9ce-1d3b3c30a1ea","quote":"The kites rise highest against the wind, not with it.","topic":"Nghị lực & Vượt khó","author":"John Neal","status":"draft","meaning":"Những con diều bay cao nhất là khi ngược gió, chứ không phải xuôi theo gió.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c4beb20a-bfad-4f77-b0de-60e08db96792","quote":"It does not matter how slowly you go as long as you do not stop.","topic":"Nghị lực & Vượt khó","author":"Khổng Tử","status":"draft","meaning":"Không quan trọng bạn đi chậm thế nào, miễn là bạn không dừng lại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7a5be617-7ef6-4e45-9dcc-fbf51df6dab0","quote":"Our greatest glory is not in never falling, but in rising every time we fall.","topic":"Nghị lực & Vượt khó","author":"Oliver Goldsmith","status":"approved","meaning":"Vinh quang lớn nhất của chúng ta không phải là không bao giờ vấp ngã, mà là đứng dậy sau mỗi lần ngã.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"17f52a3b-17b0-4395-9752-2cd12a65b6f8","quote":"Fall seven times, stand up eight.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Nhật Bản","status":"approved","meaning":"Ngã bảy lần, đứng dậy tám lần.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"115b5cae-3c28-461b-8da7-d8dcf1532d62","quote":"Never, never, never give up.","topic":"Nghị lực & Vượt khó","author":"Winston Churchill","status":"approved","meaning":"Không bao giờ, không bao giờ, không bao giờ bỏ cuộc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7b964db7-1dd5-4c98-b93e-e96baeb9443a","quote":"Difficulties strengthen the mind, as labor does the body.","topic":"Nghị lực & Vượt khó","author":"Seneca","status":"approved","meaning":"Khó khăn rèn luyện tâm trí, như lao động rèn luyện cơ thể.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b86f7837-858d-4ceb-92a9-35d5391128ab","quote":"A gem cannot be polished without friction, nor a man perfected without trials.","topic":"Nghị lực & Vượt khó","author":"Seneca","status":"draft","meaning":"Viên ngọc không thể sáng nếu không được mài giũa, con người không thể hoàn thiện nếu không trải qua thử thách.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"803f3838-5c8b-4e6e-8c88-800dd55f4d87","quote":"I have not failed. I've just found 10,000 ways that won't work.","topic":"Nghị lực & Vượt khó","author":"Thomas Edison","status":"draft","meaning":"Tôi không thất bại. Tôi chỉ vừa tìm ra 10.000 cách không hiệu quả.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c77e3ff5-d557-4ac8-bad2-4522284dddd6","quote":"It always seems impossible until it's done.","topic":"Nghị lực & Vượt khó","author":"Nelson Mandela","status":"draft","meaning":"Mọi thứ luôn có vẻ bất khả thi cho đến khi nó được hoàn thành.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e800568d-489e-4f8c-9135-6754523f4fd0","quote":"Although the world is full of suffering, it is also full of the overcoming of it.","topic":"Nghị lực & Vượt khó","author":"Helen Keller","status":"draft","meaning":"Dù thế giới đầy đau khổ, nó cũng đầy những sự vượt qua đau khổ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"782b8c70-8168-4d3d-810d-f6eedd1bb6d0","quote":"Character cannot be developed in ease and quiet. Only through experience of trial and suffering can the soul be strengthened.","topic":"Nghị lực & Vượt khó","author":"Helen Keller","status":"draft","meaning":"Tính cách không thể hình thành trong sự dễ dàng và yên ả. Chỉ qua thử thách và đau khổ, tâm hồn mới được tôi luyện.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"bafadf66-c910-46b4-a2ef-5ff5ff0daa0b","quote":"Rivers know this: there is no hurry. We shall get there some day.","topic":"Nghị lực & Vượt khó","author":"A. A. Milne","status":"draft","meaning":"Dòng sông hiểu điều này: chẳng cần vội. Rồi một ngày ta sẽ tới nơi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1bd6da0b-17cb-47c9-a854-a2c749976d8c","quote":"Perseverance is not a long race; it is many short races one after the other.","topic":"Nghị lực & Vượt khó","author":"Walter Elliot","status":"draft","meaning":"Kiên trì không phải là một cuộc đua dài, mà là nhiều cuộc đua ngắn nối tiếp nhau.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f331c231-09c6-4896-8643-c300f014be29","quote":"Great works are performed not by strength but by perseverance.","topic":"Nghị lực & Vượt khó","author":"Samuel Johnson","status":"approved","meaning":"Những công trình vĩ đại được hoàn thành không nhờ sức mạnh mà nhờ sự kiên trì.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e5781d7e-cf32-4227-a580-26e241c21244","quote":"Water is fluid, soft, and yielding. But water will wear away rock.","topic":"Nghị lực & Vượt khó","author":"Lão Tử","status":"draft","meaning":"Nước mềm mại và uyển chuyển, nhưng nước có thể bào mòn cả đá.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"94b95870-90bf-48cb-934a-bda4f64185e0","quote":"The man who moves a mountain begins by carrying away small stones.","topic":"Nghị lực & Vượt khó","author":"Khổng Tử","status":"draft","meaning":"Người dời được núi là người bắt đầu bằng việc khuân từng hòn đá nhỏ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"358c9ba0-2805-49b8-b750-7f65995dbae5","quote":"A smooth sea never made a skilled sailor.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Anh","status":"draft","meaning":"Biển lặng chưa bao giờ tạo nên thủy thủ giỏi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"92dedb4d-a3e2-47b3-aacf-e59d0390ca31","quote":"The best way out is always through.","topic":"Nghị lực & Vượt khó","author":"Robert Frost","status":"draft","meaning":"Lối thoát tốt nhất luôn là đi xuyên qua.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dcb3d0db-7ae1-4289-ad2e-196b6c37067b","quote":"When everything seems to be going against you, remember that the airplane takes off against the wind, not with it.","topic":"Nghị lực & Vượt khó","author":"Henry Ford","status":"draft","meaning":"Khi mọi thứ dường như chống lại bạn, hãy nhớ rằng máy bay cất cánh ngược gió, không phải xuôi gió.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"49094247-5a57-4c8f-b813-2d6c1cdb18fd","quote":"The darkest hour has only sixty minutes.","topic":"Nghị lực & Vượt khó","author":"Morris Mandel","status":"draft","meaning":"Giờ phút đen tối nhất cũng chỉ có sáu mươi phút.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"84a58b9d-45ad-495d-b399-22bf045352a9","quote":"Tough times never last, but tough people do.","topic":"Nghị lực & Vượt khó","author":"Robert H. Schuller","status":"draft","meaning":"Thời gian khó khăn không kéo dài mãi, nhưng con người kiên cường thì có.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cf51c49d-5a80-4f32-bffd-00cf3c7cc168","quote":"Energy and persistence conquer all things.","topic":"Nghị lực & Vượt khó","author":"Benjamin Franklin","status":"approved","meaning":"Năng lượng và sự bền bỉ chinh phục mọi thứ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5827d6f1-5d8c-4e7c-92b1-177c7eb66181","quote":"In the middle of difficulty lies opportunity.","topic":"Nghị lực & Vượt khó","author":"Albert Einstein","status":"draft","meaning":"Giữa khó khăn luôn ẩn chứa cơ hội.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8f451de1-7fe7-41f1-bf0a-8cb30490bf32","quote":"A person who never made a mistake never tried anything new.","topic":"Nghị lực & Vượt khó","author":"Albert Einstein","status":"draft","meaning":"Người chưa từng mắc sai lầm là người chưa từng thử điều gì mới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"03c97ef6-5238-4bc1-9ef9-2c0957464346","quote":"Failure is simply the opportunity to begin again, this time more intelligently.","topic":"Nghị lực & Vượt khó","author":"Henry Ford","status":"approved","meaning":"Thất bại đơn giản là cơ hội để bắt đầu lại, lần này thông minh hơn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"964bbcac-2cbc-4a9f-ad91-46dd4e862188","quote":"Whether you think you can, or you think you can't, you're right.","topic":"Nghị lực & Vượt khó","author":"Henry Ford","status":"draft","meaning":"Dù bạn nghĩ mình làm được hay không làm được, bạn đều đúng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ef6937f7-66d7-4515-a674-abc088c8382a","quote":"Ever tried. Ever failed. No matter. Try again. Fail again. Fail better.","topic":"Nghị lực & Vượt khó","author":"Samuel Beckett","status":"draft","meaning":"Đã từng thử. Đã từng thất bại. Không sao. Thử lại. Thất bại lại. Thất bại tốt hơn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4f0463a4-2348-4ddf-810f-73a0ab619ca3","quote":"Only those who dare to fail greatly can ever achieve greatly.","topic":"Nghị lực & Vượt khó","author":"Robert F. Kennedy","status":"draft","meaning":"Chỉ những ai dám thất bại lớn mới có thể đạt được thành tựu lớn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3597dae4-5c62-4232-b53e-48c59515416d","quote":"Out of difficulties grow miracles.","topic":"Nghị lực & Vượt khó","author":"Jean de La Bruyère","status":"approved","meaning":"Phép màu nảy sinh từ những khó khăn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fcb0b5a3-385d-48da-8ea5-507b73db822e","quote":"Turn your wounds into wisdom.","topic":"Nghị lực & Vượt khó","author":"Oprah Winfrey","status":"draft","meaning":"Hãy biến vết thương thành trí tuệ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6bf5722f-476e-40ba-8b09-43a27c5a5b0a","quote":"The wound is the place where the Light enters you.","topic":"Nghị lực & Vượt khó","author":"Rumi","status":"draft","meaning":"Vết thương là nơi ánh sáng đi vào bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"74ab5fa9-36ec-4edd-bdcd-23bcc3242437","quote":"Stars can't shine without darkness.","topic":"Nghị lực & Vượt khó","author":"Khuyết danh","status":"draft","meaning":"Những vì sao không thể tỏa sáng nếu thiếu bóng tối.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"812b9685-73f7-4018-8c9e-331cee284db8","quote":"The oak fought the wind and was broken, the willow bent when it must and survived.","topic":"Nghị lực & Vượt khó","author":"Robert Jordan","status":"draft","meaning":"Cây sồi chống lại gió và bị gãy, cây liễu biết uốn mình khi cần và sống sót.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"91cc2da0-42eb-416a-b502-95e0043a9d7f","quote":"Every adversity carries with it the seed of an equal or greater benefit.","topic":"Nghị lực & Vượt khó","author":"Napoleon Hill","status":"draft","meaning":"Mỗi nghịch cảnh đều mang trong nó hạt giống của một lợi ích tương đương hoặc lớn hơn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"40f52003-8519-46e3-b473-c2047d2b9e81","quote":"You may encounter many defeats, but you must not be defeated.","topic":"Nghị lực & Vượt khó","author":"Maya Angelou","status":"draft","meaning":"Bạn có thể gặp nhiều thất bại, nhưng bạn không được để mình bị đánh bại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2cff3854-5eab-4a91-bdc1-ac7094120a86","quote":"Still, like air, I'll rise.","topic":"Nghị lực & Vượt khó","author":"Maya Angelou","status":"draft","meaning":"Vậy mà, như không khí, tôi vẫn sẽ vươn lên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9c1e3fca-2314-4c87-9da1-fa38ed7593f7","quote":"A man can be destroyed but not defeated.","topic":"Nghị lực & Vượt khó","author":"Ernest Hemingway","status":"draft","meaning":"Con người có thể bị hủy diệt nhưng không thể bị đánh bại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fe635310-fcd8-4f27-9037-3316b0e79f12","quote":"The world breaks everyone, and afterward many are strong at the broken places.","topic":"Nghị lực & Vượt khó","author":"Ernest Hemingway","status":"draft","meaning":"Thế giới làm tổn thương mọi người, và sau đó nhiều người trở nên mạnh mẽ ở chính những chỗ từng vỡ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"30ca62b3-b364-49cc-98b8-41b689c68af1","quote":"Rock bottom became the solid foundation on which I rebuilt my life.","topic":"Nghị lực & Vượt khó","author":"J. K. Rowling","status":"draft","meaning":"Đáy vực đã trở thành nền móng vững chắc để tôi xây dựng lại cuộc đời.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"abb3a1a7-6149-4a6c-ab05-880d88d0f0c2","quote":"I am not afraid of storms, for I am learning how to sail my ship.","topic":"Nghị lực & Vượt khó","author":"Louisa May Alcott","status":"approved","meaning":"Tôi không sợ bão tố, vì tôi đang học cách lái con tàu của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5e54ed04-787d-4e11-91e2-7b3a714dfe3e","quote":"Genius is one percent inspiration and ninety-nine percent perspiration.","topic":"Nghị lực & Vượt khó","author":"Thomas Edison","status":"approved","meaning":"Thiên tài là một phần trăm cảm hứng và chín mươi chín phần trăm mồ hôi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"30e5871f-2461-43ef-80f5-6f846299e859","quote":"Obstacles are those frightful things you see when you take your eyes off your goal.","topic":"Nghị lực & Vượt khó","author":"Henry Ford","status":"draft","meaning":"Chướng ngại là những thứ đáng sợ bạn thấy khi rời mắt khỏi mục tiêu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"61505146-63ee-49f8-8ed1-c87736df34fe","quote":"Nothing is impossible to a willing heart.","topic":"Nghị lực & Vượt khó","author":"John Heywood","status":"approved","meaning":"Không gì là không thể với một trái tim quyết tâm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"37fe9e2d-808a-4711-9637-963cc0db9a81","quote":"Where there is a will, there is a way.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Anh","status":"approved","meaning":"Ở đâu có ý chí, ở đó có con đường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4c5c09a7-b485-449c-92be-fb4d1ccf1121","quote":"After a storm comes a calm.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Anh","status":"approved","meaning":"Sau cơn bão là trời yên biển lặng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"747b440e-164c-47aa-a786-ea9499c12acd","quote":"Even the darkest night will end and the sun will rise.","topic":"Nghị lực & Vượt khó","author":"Victor Hugo","status":"draft","meaning":"Ngay cả đêm tối nhất rồi cũng qua và mặt trời sẽ mọc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1a1f632c-68e6-4561-a552-3be614e2d758","quote":"Failure is the mother of success.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Thất bại là mẹ thành công.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"976ab816-77dd-4f65-9b02-d19e0d58a931","quote":"Fire tests gold; hardship tests strength.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Lửa thử vàng, gian nan thử sức.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"811d07f1-d153-41d1-a83d-c3e0ce90ea6a","quote":"Flowing water wears away stone.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Nước chảy đá mòn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"472ed2e8-b818-4887-9fd8-4ae6ee3f4cc4","quote":"Ants carrying bit by bit will eventually fill their nest.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Kiến tha lâu đầy tổ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dce54cb5-a190-4cb6-a875-4f2cf34de36f","quote":"Nothing is hard; only fear a heart that won't persevere. Dig mountains, fill seas: with resolve, it will be done.","topic":"Nghị lực & Vượt khó","author":"Hồ Chí Minh","status":"draft","meaning":"Không có việc gì khó, chỉ sợ lòng không bền; đào núi và lấp biển, quyết chí ắt làm nên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ea331374-5b33-4dea-af73-dda933b7dfae","quote":"Don't drop your oars just because you see big waves.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Chớ thấy sóng cả mà ngã tay chèo.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5af2b59f-c8e4-439d-8153-3827101e1368","quote":"Where there is will, there is success.","topic":"Nghị lực & Vượt khó","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Có chí thì nên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7f5cc689-d1a4-4490-8d24-91aa31833391","quote":"The journey of a thousand miles begins with a single step.","topic":"Thành công & Hành động","author":"Lão Tử","status":"approved","meaning":"Hành trình vạn dặm bắt đầu từ một bước chân.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4e1579d6-03b2-489d-845c-2c53d957e490","quote":"Well done is better than well said.","topic":"Thành công & Hành động","author":"Benjamin Franklin","status":"approved","meaning":"Làm tốt thì hơn nói hay.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1f1ec571-b609-43b2-968a-5ea45929a907","quote":"An investment in knowledge pays the best interest.","topic":"Thành công & Hành động","author":"Benjamin Franklin","status":"draft","meaning":"Đầu tư vào tri thức mang lại lợi nhuận cao nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8de1d1f6-d2c5-44f3-b8ae-cf03bb192b4d","quote":"By failing to prepare, you are preparing to fail.","topic":"Thành công & Hành động","author":"Benjamin Franklin","status":"draft","meaning":"Không chuẩn bị tức là đang chuẩn bị cho thất bại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6654d930-4486-4920-a49b-ff8d305ed429","quote":"Quality is not an act, it is a habit.","topic":"Thành công & Hành động","author":"Aristotle","status":"draft","meaning":"Chất lượng không phải là một hành động, mà là một thói quen.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1390684f-9dc7-450b-9b7c-0d586e0cad87","quote":"Well begun is half done.","topic":"Thành công & Hành động","author":"Aristotle","status":"approved","meaning":"Khởi đầu tốt là đã xong một nửa.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0ce8ac7e-235e-4df5-9835-ade19518c6e4","quote":"The secret of getting ahead is getting started.","topic":"Thành công & Hành động","author":"Mark Twain","status":"draft","meaning":"Bí quyết để tiến lên là bắt đầu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"12af098b-d35f-43e5-ab3e-19d8e6db3321","quote":"Plans are nothing; planning is everything.","topic":"Thành công & Hành động","author":"Dwight D. Eisenhower","status":"draft","meaning":"Kế hoạch chẳng là gì, việc lập kế hoạch mới là tất cả.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9025006a-eac0-4586-aa38-dd914908a4a7","quote":"Opportunity is missed by most people because it is dressed in overalls and looks like work.","topic":"Thành công & Hành động","author":"Thomas Edison","status":"draft","meaning":"Hầu hết mọi người bỏ lỡ cơ hội vì nó mặc bộ đồ lao động và trông giống như công việc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dc3c12b9-54e2-4e7b-bfe8-91af0bf2ed35","quote":"There is no substitute for hard work.","topic":"Thành công & Hành động","author":"Thomas Edison","status":"draft","meaning":"Không gì có thể thay thế được sự chăm chỉ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"410070e5-0e80-4d02-8719-0cc3984a8f12","quote":"Luck is what happens when preparation meets opportunity.","topic":"Thành công & Hành động","author":"Seneca","status":"draft","meaning":"May mắn là khi sự chuẩn bị gặp được cơ hội.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ab0669f0-d5f0-4152-9c8f-83cade6be983","quote":"Action is the foundational key to all success.","topic":"Thành công & Hành động","author":"Pablo Picasso","status":"draft","meaning":"Hành động là chìa khóa nền tảng của mọi thành công.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d4aa625b-79e0-4072-a3b9-908b17b20ea0","quote":"Do what you can, with what you have, where you are.","topic":"Thành công & Hành động","author":"Theodore Roosevelt","status":"approved","meaning":"Hãy làm những gì bạn có thể, với những gì bạn có, ở nơi bạn đang đứng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"809482ee-ac52-4315-922d-799adccf803a","quote":"Believe you can and you're halfway there.","topic":"Thành công & Hành động","author":"Theodore Roosevelt","status":"draft","meaning":"Tin rằng mình làm được là bạn đã đi được nửa đường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f98dc892-4c74-4717-8611-dd23b916530b","quote":"Success usually comes to those who are too busy to be looking for it.","topic":"Thành công & Hành động","author":"Henry David Thoreau","status":"draft","meaning":"Thành công thường đến với những người quá bận rộn để đi tìm nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4fb82dc0-e088-4b36-93ce-1cde9c4c17b1","quote":"Go confidently in the direction of your dreams. Live the life you have imagined.","topic":"Thành công & Hành động","author":"Henry David Thoreau","status":"draft","meaning":"Hãy tự tin bước theo hướng ước mơ của bạn. Hãy sống cuộc đời bạn đã hình dung.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"eb6bb61a-681a-40fc-b039-86e89c7e5278","quote":"Do not wait to strike till the iron is hot; but make it hot by striking.","topic":"Thành công & Hành động","author":"William Butler Yeats","status":"draft","meaning":"Đừng đợi sắt nóng mới rèn; hãy rèn cho sắt nóng lên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"441f9261-3e7b-4f76-88f3-1bedc864106e","quote":"Knowing is not enough; we must apply. Willing is not enough; we must do.","topic":"Thành công & Hành động","author":"Johann Wolfgang von Goethe","status":"approved","meaning":"Biết thôi chưa đủ, ta phải áp dụng. Muốn thôi chưa đủ, ta phải làm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7fa76058-e6a9-4605-b539-6d1ed8735b8b","quote":"Talent wins games, but teamwork and intelligence win championships.","topic":"Thành công & Hành động","author":"Michael Jordan","status":"draft","meaning":"Tài năng thắng trận đấu, nhưng tinh thần đồng đội và trí tuệ mới giành chức vô địch.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e31593a4-ffb1-4f20-9b1d-9cbcb245ed13","quote":"I've failed over and over and over again in my life. And that is why I succeed.","topic":"Thành công & Hành động","author":"Michael Jordan","status":"draft","meaning":"Tôi đã thất bại hết lần này đến lần khác trong đời. Và đó là lý do tôi thành công.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c1b398b8-2e39-4fe0-886a-28895b7b582c","quote":"You miss 100% of the shots you don't take.","topic":"Thành công & Hành động","author":"Wayne Gretzky","status":"draft","meaning":"Bạn bỏ lỡ 100% những cú sút mà bạn không thực hiện.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a39d4a4d-28dc-4c89-bf0e-166da7d25d08","quote":"The way to get started is to quit talking and begin doing.","topic":"Thành công & Hành động","author":"Walt Disney","status":"draft","meaning":"Cách để bắt đầu là ngừng nói và bắt tay vào làm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"bbacb874-4d85-4bc7-9e62-7ec05971ca9b","quote":"All our dreams can come true, if we have the courage to pursue them.","topic":"Thành công & Hành động","author":"Walt Disney","status":"draft","meaning":"Mọi giấc mơ đều có thể thành hiện thực nếu ta có đủ can đảm theo đuổi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fb8e9277-883e-4281-8fc8-bb98e0ec190e","quote":"Don't watch the clock; do what it does. Keep going.","topic":"Thành công & Hành động","author":"Sam Levenson","status":"draft","meaning":"Đừng nhìn đồng hồ; hãy làm như nó: tiếp tục chạy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5c957eaf-4c7c-4380-ab78-828cc1102cb6","quote":"The future depends on what you do today.","topic":"Thành công & Hành động","author":"Mahatma Gandhi","status":"draft","meaning":"Tương lai phụ thuộc vào những gì bạn làm hôm nay.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"29f4dbde-5836-42c5-b618-e1d53b278cff","quote":"Small deeds done are better than great deeds planned.","topic":"Thành công & Hành động","author":"Peter Marshall","status":"approved","meaning":"Việc nhỏ đã làm tốt hơn việc lớn chỉ dự định.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5269b1bb-f7de-48a9-9a4d-e1a5da34e561","quote":"The best way to predict the future is to create it.","topic":"Thành công & Hành động","author":"Peter Drucker","status":"draft","meaning":"Cách tốt nhất để dự đoán tương lai là tạo ra nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8aacec08-bced-4082-a6e1-d9aa2ec297f3","quote":"Efficiency is doing things right; effectiveness is doing the right things.","topic":"Thành công & Hành động","author":"Peter Drucker","status":"draft","meaning":"Hiệu suất là làm đúng cách; hiệu quả là làm đúng việc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8f4de03d-85b2-4fc7-83d0-559b1d4f3d43","quote":"Stay hungry, stay foolish.","topic":"Thành công & Hành động","author":"Stewart Brand","status":"draft","meaning":"Hãy cứ khát khao, hãy cứ dại khờ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2d5fff73-f016-4ef5-8e4d-057c933c5c5c","quote":"Your time is limited, so don't waste it living someone else's life.","topic":"Thành công & Hành động","author":"Steve Jobs","status":"draft","meaning":"Thời gian của bạn có hạn, đừng lãng phí nó để sống cuộc đời của người khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c070ec0d-592a-41a9-97dc-75e520d03c04","quote":"The only way to do great work is to love what you do.","topic":"Thành công & Hành động","author":"Steve Jobs","status":"draft","meaning":"Cách duy nhất để làm việc tuyệt vời là yêu những gì bạn làm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"74379874-cfff-4c4b-8ada-b0ae7cd1af26","quote":"Innovation distinguishes between a leader and a follower.","topic":"Thành công & Hành động","author":"Steve Jobs","status":"draft","meaning":"Đổi mới là điều phân biệt người dẫn đầu với người theo sau.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"682fd5c8-a862-42a6-b486-00f87258ce74","quote":"If opportunity doesn't knock, build a door.","topic":"Thành công & Hành động","author":"Milton Berle","status":"draft","meaning":"Nếu cơ hội không gõ cửa, hãy tự xây một cánh cửa.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"acd02d2b-b0c1-4f15-8c24-577f83db8081","quote":"Don't count the days, make the days count.","topic":"Thành công & Hành động","author":"Muhammad Ali","status":"draft","meaning":"Đừng đếm ngày, hãy làm cho mỗi ngày đều có giá trị.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a6c720ae-0611-4ed3-a31f-987d15b5fa7e","quote":"Impossible is just a big word thrown around by small men.","topic":"Thành công & Hành động","author":"Muhammad Ali","status":"draft","meaning":"Không thể chỉ là một từ to tát được những kẻ nhỏ bé ném ra.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"02b01fc2-3eb0-4834-955e-d68481fb99f6","quote":"The man who has confidence in himself gains the confidence of others.","topic":"Thành công & Hành động","author":"Tục ngữ Do Thái","status":"draft","meaning":"Người tin vào bản thân sẽ có được niềm tin của người khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"57d6d6d3-05e6-4362-a9be-34012e3bc229","quote":"Hard work beats talent when talent doesn't work hard.","topic":"Thành công & Hành động","author":"Tim Notke","status":"draft","meaning":"Chăm chỉ đánh bại tài năng khi tài năng không chăm chỉ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7d938574-5354-490f-86e0-8860e7375bdf","quote":"Success is not the key to happiness. Happiness is the key to success.","topic":"Thành công & Hành động","author":"Albert Schweitzer","status":"draft","meaning":"Thành công không phải là chìa khóa của hạnh phúc. Hạnh phúc mới là chìa khóa của thành công.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"28c49f80-e2ae-40a5-bdcd-52c8d8165a07","quote":"Real knowledge is to know the extent of one's ignorance.","topic":"Thành công & Hành động","author":"Khổng Tử","status":"draft","meaning":"Hiểu biết thật sự là biết được mức độ thiếu hiểu biết của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3a07c2af-888a-4603-aaca-60311feab7cf","quote":"Act without expectation.","topic":"Thành công & Hành động","author":"Lão Tử","status":"draft","meaning":"Hãy hành động mà không kỳ vọng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"23e0f317-fcf1-429f-8e8f-9b81e3d36b21","quote":"Nature does not hurry, yet everything is accomplished.","topic":"Thành công & Hành động","author":"Lão Tử","status":"draft","meaning":"Thiên nhiên không vội vã, vậy mà mọi thứ đều được hoàn thành.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b3ddd943-8030-420b-bcf9-440419dc19d9","quote":"Do the difficult things while they are easy and do the great things while they are small.","topic":"Thành công & Hành động","author":"Lão Tử","status":"approved","meaning":"Hãy làm việc khó khi nó còn dễ, làm việc lớn khi nó còn nhỏ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9d515f1e-37ba-49e5-a433-675ec6b8320f","quote":"In the midst of chaos, there is also opportunity.","topic":"Thành công & Hành động","author":"Tôn Tử","status":"draft","meaning":"Giữa hỗn loạn cũng có cơ hội.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2531b87c-4698-4217-b00a-12200ba7273f","quote":"Great things are not done by impulse, but by a series of small things brought together.","topic":"Thành công & Hành động","author":"Vincent van Gogh","status":"approved","meaning":"Những điều vĩ đại không được làm bởi bốc đồng, mà bởi chuỗi việc nhỏ gộp lại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a1092ba6-9999-40cc-96f2-c9eea32b781e","quote":"What would life be if we had no courage to attempt anything?","topic":"Thành công & Hành động","author":"Vincent van Gogh","status":"approved","meaning":"Cuộc đời sẽ ra sao nếu ta không có can đảm thử bất cứ điều gì?","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d6e1d434-e975-4f19-aa67-e494354ab68d","quote":"Inspiration exists, but it has to find you working.","topic":"Thành công & Hành động","author":"Pablo Picasso","status":"draft","meaning":"Cảm hứng có tồn tại, nhưng nó phải thấy bạn đang làm việc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ba3d6f6a-942e-4b91-b49a-7f805ab9381e","quote":"Everything you can imagine is real.","topic":"Thành công & Hành động","author":"Pablo Picasso","status":"draft","meaning":"Mọi thứ bạn có thể tưởng tượng đều là thật.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"419c7630-445e-4220-abe7-a77217687f79","quote":"Ideas are easy. Implementation is hard.","topic":"Thành công & Hành động","author":"Guy Kawasaki","status":"draft","meaning":"Ý tưởng thì dễ. Thực hiện mới khó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f44f42ed-ed83-45a3-acd2-32d16cbbe902","quote":"Done is better than perfect.","topic":"Thành công & Hành động","author":"Sheryl Sandberg","status":"draft","meaning":"Hoàn thành tốt hơn hoàn hảo.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c96084d7-4043-473c-9628-8a605f225ea1","quote":"The successful warrior is the average man, with laser-like focus.","topic":"Thành công & Hành động","author":"Bruce Lee","status":"draft","meaning":"Chiến binh thành công là người bình thường với sự tập trung như tia laser.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3f2fa0ec-cfdc-4bb4-aef9-730fd5bdd507","quote":"A dream doesn't become reality through magic; it takes sweat, determination and hard work.","topic":"Thành công & Hành động","author":"Colin Powell","status":"draft","meaning":"Giấc mơ không thành hiện thực nhờ phép màu; nó cần mồ hôi, quyết tâm và lao động chăm chỉ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"13f336cb-7b9e-4edc-81b4-ef7a46709183","quote":"There are no secrets to success. It is the result of preparation, hard work, and learning from failure.","topic":"Thành công & Hành động","author":"Colin Powell","status":"draft","meaning":"Không có bí mật nào cho thành công. Đó là kết quả của sự chuẩn bị, chăm chỉ và học hỏi từ thất bại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c8194ef8-796c-40ee-a4e6-68e48c9292a5","quote":"Don't be afraid to give up the good to go for the great.","topic":"Thành công & Hành động","author":"John D. Rockefeller","status":"draft","meaning":"Đừng sợ từ bỏ điều tốt để theo đuổi điều tuyệt vời.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"64e9f70a-24ad-4420-a523-6049a68f0119","quote":"Motivation is what gets you started. Habit is what keeps you going.","topic":"Thành công & Hành động","author":"Jim Ryun","status":"draft","meaning":"Động lực giúp bạn bắt đầu. Thói quen giúp bạn tiếp tục.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"43c9c9c6-9f3c-4225-a211-7c69da7e9431","quote":"Discipline is the bridge between goals and accomplishment.","topic":"Thành công & Hành động","author":"Jim Rohn","status":"draft","meaning":"Kỷ luật là cây cầu nối giữa mục tiêu và thành tựu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"253ee809-d969-4cfc-9c5b-fb40a2fa0195","quote":"Either you run the day or the day runs you.","topic":"Thành công & Hành động","author":"Jim Rohn","status":"draft","meaning":"Hoặc bạn điều khiển ngày của mình, hoặc ngày điều khiển bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"43df4478-c037-4bdb-83ad-2c9e45f3c6a0","quote":"Success is nothing more than a few simple disciplines, practiced every day.","topic":"Thành công & Hành động","author":"Jim Rohn","status":"draft","meaning":"Thành công chẳng qua là vài thói quen kỷ luật đơn giản, được thực hành mỗi ngày.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7b96caa9-9a29-492d-8a11-45642771f5cc","quote":"You don't have to be great to start, but you have to start to be great.","topic":"Thành công & Hành động","author":"Zig Ziglar","status":"draft","meaning":"Bạn không cần giỏi mới bắt đầu, nhưng phải bắt đầu mới trở nên giỏi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"77944861-ab70-4243-939d-d92a04e23c1f","quote":"People often say that motivation doesn't last. Well, neither does bathing. That's why we recommend it daily.","topic":"Thành công & Hành động","author":"Zig Ziglar","status":"draft","meaning":"Người ta thường nói động lực không kéo dài. Tắm cũng vậy, nên ta mới khuyên làm mỗi ngày.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"267db949-f71f-4db8-a08a-2b537b924c30","quote":"A hundred good ideas are not worth one practiced hand.","topic":"Thành công & Hành động","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Trăm hay không bằng tay quen.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"30b65667-e835-468b-baef-5b160c3c8ee8","quote":"The bad news is time flies. The good news is you're the pilot.","topic":"Thời gian & Hiện tại","author":"Michael Altshuler","status":"draft","meaning":"Tin xấu là thời gian bay vụt qua. Tin tốt là bạn chính là phi công.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d1808e9e-b1ad-462b-afd8-782755d790a8","quote":"Yesterday is history, tomorrow is a mystery, today is a gift. That's why it is called the present.","topic":"Thời gian & Hiện tại","author":"Alice Morse Earle","status":"draft","meaning":"Hôm qua là lịch sử, ngày mai là điều bí ẩn, hôm nay là món quà. Vì thế nó được gọi là hiện tại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9490a89f-048b-4b97-9c6f-0a55c81e6aec","quote":"Life is available only in the present moment.","topic":"Thời gian & Hiện tại","author":"Thích Nhất Hạnh","status":"draft","meaning":"Sự sống chỉ có mặt trong giây phút hiện tại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1511337b-f130-4f16-94f6-c3cf545f3d67","quote":"Walk as if you are kissing the Earth with your feet.","topic":"Thời gian & Hiện tại","author":"Thích Nhất Hạnh","status":"draft","meaning":"Hãy bước đi như thể bàn chân bạn đang hôn lên mặt đất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f2cc4847-3e52-4c33-9070-a126c076f66e","quote":"Today is the tomorrow you worried about yesterday.","topic":"Thời gian & Hiện tại","author":"Dale Carnegie","status":"draft","meaning":"Hôm nay chính là ngày mai mà hôm qua bạn lo lắng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"aa6bf14f-1a88-4445-a5de-074741bf172e","quote":"Time you enjoy wasting is not wasted time.","topic":"Thời gian & Hiện tại","author":"Marthe Troly-Curtin","status":"draft","meaning":"Thời gian bạn tận hưởng việc lãng phí thì không phải là thời gian lãng phí.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f708ed7e-95c6-4de3-8363-3815ec678cc7","quote":"The best time to plant a tree was 20 years ago. The second best time is now.","topic":"Thời gian & Hiện tại","author":"Tục ngữ Trung Hoa","status":"draft","meaning":"Thời điểm tốt nhất để trồng cây là 20 năm trước. Thời điểm tốt thứ hai là bây giờ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2866010d-b0cd-42ea-8701-dc75f369af71","quote":"Forever is composed of nows.","topic":"Thời gian & Hiện tại","author":"Emily Dickinson","status":"approved","meaning":"Vĩnh cửu được tạo nên từ những khoảnh khắc hiện tại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5ca291a7-19f4-4bed-8282-aa7d4cf16a21","quote":"The trouble is, you think you have time.","topic":"Thời gian & Hiện tại","author":"Jack Kornfield","status":"draft","meaning":"Vấn đề là bạn nghĩ mình còn thời gian.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7146153e-db88-447f-9466-adea864b11ed","quote":"If you want to eat, get into the kitchen.","topic":"Thành công & Hành động","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Muốn ăn thì lăn vào bếp.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4713cf9b-0ec7-4184-916e-449293e66ebc","quote":"Time heals what reason cannot.","topic":"Thời gian & Hiện tại","author":"Seneca","status":"draft","meaning":"Thời gian chữa lành những gì lý trí không thể.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"620ad559-3087-4e74-bfe9-b97d98724527","quote":"Time is the longest distance between two places.","topic":"Thời gian & Hiện tại","author":"Tennessee Williams","status":"draft","meaning":"Thời gian là khoảng cách dài nhất giữa hai nơi chốn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dd5205f7-063f-4e77-963e-ffb0bb7c4f70","quote":"The time is always right to do what is right.","topic":"Thời gian & Hiện tại","author":"Martin Luther King Jr.","status":"draft","meaning":"Lúc nào cũng là thời điểm đúng để làm điều đúng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"68e3e408-5dac-40e4-a19a-c1d85ae4ce62","quote":"Tomorrow is often the busiest day of the week.","topic":"Thời gian & Hiện tại","author":"Tục ngữ Tây Ban Nha","status":"approved","meaning":"Ngày mai thường là ngày bận rộn nhất trong tuần.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"743f59f7-d46f-4b73-9c27-bb51c829411e","quote":"Don't wait. The time will never be just right.","topic":"Thời gian & Hiện tại","author":"Napoleon Hill","status":"draft","meaning":"Đừng chờ đợi. Sẽ không bao giờ có thời điểm hoàn hảo.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0c59b35f-84e1-4381-8d18-b47ddf7d584c","quote":"Time is free, but it's priceless. You can't own it, but you can use it.","topic":"Thời gian & Hiện tại","author":"Harvey Mackay","status":"draft","meaning":"Thời gian miễn phí nhưng vô giá. Bạn không thể sở hữu nó, nhưng có thể sử dụng nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"09eff770-90c2-4cf1-b00a-98e496f7afdf","quote":"The key is in not spending time, but in investing it.","topic":"Thời gian & Hiện tại","author":"Stephen R. Covey","status":"draft","meaning":"Bí quyết không nằm ở việc tiêu thời gian, mà ở việc đầu tư nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ed0436e5-3e68-47cb-ba23-8505a5663f47","quote":"The key is not to prioritize what's on your schedule, but to schedule your priorities.","topic":"Thời gian & Hiện tại","author":"Stephen R. Covey","status":"draft","meaning":"Bí quyết không phải là ưu tiên những gì trên lịch, mà là xếp lịch cho những điều ưu tiên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"70aae9b1-a79f-408a-993b-f9b475500fed","quote":"Realize deeply that the present moment is all you have.","topic":"Thời gian & Hiện tại","author":"Eckhart Tolle","status":"draft","meaning":"Hãy thấu hiểu sâu sắc rằng khoảnh khắc hiện tại là tất cả những gì bạn có.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c79cddf2-5793-4857-b9b3-574c1135baa4","quote":"How did it get so late so soon?","topic":"Thời gian & Hiện tại","author":"Dr. Seuss","status":"draft","meaning":"Sao mới đó đã muộn thế này?","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3be023cd-b4ef-415f-9c38-681ef28e5d62","quote":"Time stays long enough for anyone who will use it.","topic":"Thời gian & Hiện tại","author":"Leonardo da Vinci","status":"approved","meaning":"Thời gian luôn đủ dài cho bất cứ ai biết sử dụng nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"544a434c-ea78-4566-95d1-eee07649bfb8","quote":"The only reason for time is so that everything doesn't happen at once.","topic":"Thời gian & Hiện tại","author":"Albert Einstein","status":"draft","meaning":"Lý do duy nhất để có thời gian là để mọi thứ không xảy ra cùng một lúc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c73e3192-5b95-4705-b3ce-db5b318e8342","quote":"Each moment is a place you've never been.","topic":"Thời gian & Hiện tại","author":"Mark Strand","status":"draft","meaning":"Mỗi khoảnh khắc là một nơi bạn chưa từng đến.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"01aaca0b-d138-480b-bf92-e9026f41a608","quote":"One today is worth two tomorrows.","topic":"Thời gian & Hiện tại","author":"Benjamin Franklin","status":"approved","meaning":"Một ngày hôm nay đáng giá hai ngày mai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a3b32841-e39f-4621-9ba5-3f45ffc29a24","quote":"The present is the point at which time touches eternity.","topic":"Thời gian & Hiện tại","author":"C. S. Lewis","status":"draft","meaning":"Hiện tại là điểm mà thời gian chạm vào vĩnh cửu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f06371bb-2b0c-491d-acc7-ba7842430a2a","quote":"With the new day comes new strength and new thoughts.","topic":"Thời gian & Hiện tại","author":"Eleanor Roosevelt","status":"draft","meaning":"Ngày mới mang đến sức mạnh mới và suy nghĩ mới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b7e8309b-b49c-4c41-b892-c0ec3ddbd169","quote":"Yesterday is gone. Tomorrow has not yet come. We have only today. Let us begin.","topic":"Thời gian & Hiện tại","author":"Mẹ Teresa","status":"draft","meaning":"Hôm qua đã qua. Ngày mai chưa đến. Ta chỉ có hôm nay. Hãy bắt đầu thôi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d9a0e2ef-be75-4ef1-a525-b595a5933306","quote":"Time is the coin of your life. Only you can determine how it will be spent.","topic":"Thời gian & Hiện tại","author":"Carl Sandburg","status":"draft","meaning":"Thời gian là đồng tiền của cuộc đời bạn. Chỉ bạn mới quyết định nó được tiêu thế nào.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dead5f5b-6e83-4a8f-98e7-35d4fe35782f","quote":"Until we can manage time, we can manage nothing else.","topic":"Thời gian & Hiện tại","author":"Peter Drucker","status":"draft","meaning":"Chừng nào chưa quản lý được thời gian, ta không quản lý được gì khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"befb523c-a042-4086-83e7-82f9ccb02fee","quote":"Time is the school in which we learn, time is the fire in which we burn.","topic":"Thời gian & Hiện tại","author":"Delmore Schwartz","status":"draft","meaning":"Thời gian là trường học nơi ta học hỏi, là ngọn lửa nơi ta bùng cháy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7d87070d-2dc5-4f01-8a1f-7a3d016aab5e","quote":"Do not regret growing older. It is a privilege denied to many.","topic":"Thời gian & Hiện tại","author":"Khuyết danh","status":"draft","meaning":"Đừng tiếc nuối việc già đi. Đó là đặc ân mà nhiều người không có được.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6f27ef7d-6573-4f91-b4eb-ea00e347f2d3","quote":"Age is an issue of mind over matter. If you don't mind, it doesn't matter.","topic":"Thời gian & Hiện tại","author":"Mark Twain","status":"draft","meaning":"Tuổi tác là chuyện của tâm trí. Nếu bạn không bận tâm, nó chẳng quan trọng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"491a17e1-4c95-404b-a762-1feeddb3852a","quote":"Youth is wasted on the young.","topic":"Thời gian & Hiện tại","author":"George Bernard Shaw","status":"draft","meaning":"Tuổi trẻ thật phí hoài khi trao cho người trẻ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"bd331b4d-2e9c-4c22-af5b-8b11fc417528","quote":"Miss one step, miss a whole life.","topic":"Thời gian & Hiện tại","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Lỡ một bước, lỡ cả đời.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"869af89e-9ad9-468f-a4c2-9649b5500a49","quote":"I know that I know nothing.","topic":"Học tập & Ngôn ngữ","author":"Socrates","status":"draft","meaning":"Tôi biết rằng tôi chẳng biết gì.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"26098aea-6168-4b83-a013-b0272fda4f18","quote":"The mind is not a vessel to be filled, but a fire to be kindled.","topic":"Học tập & Ngôn ngữ","author":"Plutarch","status":"approved","meaning":"Tâm trí không phải chiếc bình để đổ đầy, mà là ngọn lửa cần được nhóm lên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"04b8f6ba-626b-4a8a-9832-30e708a7d2c0","quote":"Is it not a pleasure to learn and to practice what you have learned?","topic":"Học tập & Ngôn ngữ","author":"Khổng Tử","status":"approved","meaning":"Học mà thường xuyên ôn luyện, chẳng phải là niềm vui sao?","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"46f2ea68-100f-441f-8c01-c5d332243dd3","quote":"When three people walk together, one of them can be my teacher.","topic":"Học tập & Ngôn ngữ","author":"Khổng Tử","status":"approved","meaning":"Ba người cùng đi, ắt có người là thầy ta.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7a70e8a9-e43f-42aa-ac91-2cf9274c7819","quote":"Review the old and learn the new, and you can be a teacher.","topic":"Học tập & Ngôn ngữ","author":"Khổng Tử","status":"approved","meaning":"Ôn cũ mà biết mới, có thể làm thầy được.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"66495639-f38b-4e4e-a4f0-0505d63a83b9","quote":"I hear and I forget. I see and I remember. I do and I understand.","topic":"Học tập & Ngôn ngữ","author":"Tuân Tử","status":"draft","meaning":"Tôi nghe và tôi quên. Tôi thấy và tôi nhớ. Tôi làm và tôi hiểu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"618e3586-d36d-4a5d-91ca-c5194f807f8b","quote":"The roots of education are bitter, but the fruit is sweet.","topic":"Học tập & Ngôn ngữ","author":"Aristotle","status":"draft","meaning":"Gốc rễ của học vấn thì đắng, nhưng quả của nó thì ngọt.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d510ecb7-12fd-4e40-943e-657e04ce2f36","quote":"Education is the most powerful weapon which you can use to change the world.","topic":"Học tập & Ngôn ngữ","author":"Nelson Mandela","status":"draft","meaning":"Giáo dục là vũ khí mạnh nhất bạn có thể dùng để thay đổi thế giới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7d485d6c-2c55-42a6-8930-64b99c6ebb67","quote":"Anyone who stops learning is old, whether at twenty or eighty.","topic":"Học tập & Ngôn ngữ","author":"Henry Ford","status":"draft","meaning":"Ai ngừng học thì già, dù hai mươi hay tám mươi tuổi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1ac4ee6c-b34b-4280-b3e7-6e262e5c8bf6","quote":"The important thing is not to stop questioning. Curiosity has its own reason for existing.","topic":"Học tập & Ngôn ngữ","author":"Albert Einstein","status":"approved","meaning":"Điều quan trọng là không ngừng đặt câu hỏi. Sự tò mò có lý do tồn tại của riêng nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4015ea04-5c8b-4033-bd63-0fca6df87550","quote":"I have no special talents. I am only passionately curious.","topic":"Học tập & Ngôn ngữ","author":"Albert Einstein","status":"approved","meaning":"Tôi không có tài năng đặc biệt nào. Tôi chỉ tò mò một cách say mê.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"47c9971a-85b0-4d97-a8ac-001ff1bbc8c7","quote":"Education is what remains after one has forgotten what one has learned in school.","topic":"Học tập & Ngôn ngữ","author":"Albert Einstein","status":"draft","meaning":"Giáo dục là những gì còn lại sau khi ta quên hết những gì đã học ở trường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"93fcf1e0-0342-44a7-a321-59e41e5a4e80","quote":"The beautiful thing about learning is that nobody can take it away from you.","topic":"Học tập & Ngôn ngữ","author":"B. B. King","status":"draft","meaning":"Điều tuyệt vời của việc học là không ai có thể lấy nó khỏi bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"da2bf2bc-362a-4791-a739-db39fb6e5074","quote":"Change is the end result of all true learning.","topic":"Học tập & Ngôn ngữ","author":"Leo Buscaglia","status":"draft","meaning":"Thay đổi là kết quả cuối cùng của mọi sự học thực sự.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"92c846ba-14fc-490c-9ade-d56f0dfc7bc7","quote":"Learning never exhausts the mind.","topic":"Học tập & Ngôn ngữ","author":"Leonardo da Vinci","status":"draft","meaning":"Học tập không bao giờ làm cạn kiệt trí óc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cc885adf-f6ce-4cb3-8f85-9b6bfe253e09","quote":"A room without books is like a body without a soul.","topic":"Học tập & Ngôn ngữ","author":"Cicero","status":"draft","meaning":"Căn phòng không có sách như cơ thể không có linh hồn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0d21e41c-e261-4c8b-b379-9199eafb6151","quote":"There is no friend as loyal as a book.","topic":"Học tập & Ngôn ngữ","author":"Ernest Hemingway","status":"draft","meaning":"Không có người bạn nào trung thành như một cuốn sách.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"878be3b2-6ff2-4a58-a379-0fa18e762635","quote":"A reader lives a thousand lives before he dies. The man who never reads lives only one.","topic":"Học tập & Ngôn ngữ","author":"George R. R. Martin","status":"draft","meaning":"Người đọc sách sống một nghìn cuộc đời trước khi chết. Người không bao giờ đọc chỉ sống một.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d103d7e8-d0d3-48ed-a1bb-2f674cb74180","quote":"I have never let my schooling interfere with my education.","topic":"Học tập & Ngôn ngữ","author":"Grant Allen","status":"draft","meaning":"Tôi chưa bao giờ để việc đi học cản trở việc học của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1f6aa3f7-cf53-4f68-8e70-75240ce0e1b4","quote":"The only true wisdom is in knowing you know nothing.","topic":"Học tập & Ngôn ngữ","author":"Socrates","status":"draft","meaning":"Trí tuệ thật sự duy nhất là biết rằng mình chẳng biết gì.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f950d14d-276c-4f0d-8d3b-fee793b65b0a","quote":"Wonder is the beginning of wisdom.","topic":"Học tập & Ngôn ngữ","author":"Socrates","status":"draft","meaning":"Sự ngạc nhiên là khởi đầu của trí tuệ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"205390d5-ac83-410b-b9e7-687457122828","quote":"Develop a passion for learning. If you do, you will never cease to grow.","topic":"Học tập & Ngôn ngữ","author":"Anthony J. D'Angelo","status":"draft","meaning":"Hãy nuôi dưỡng niềm đam mê học hỏi. Nếu làm được, bạn sẽ không bao giờ ngừng phát triển.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"41e8e610-a40d-47cb-9181-792223ef6a60","quote":"Learn continually. There's always one more thing to learn.","topic":"Học tập & Ngôn ngữ","author":"Steve Jobs","status":"draft","meaning":"Hãy học liên tục. Luôn có thêm một điều nữa để học.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3f90f2ff-6547-4020-bf27-f02df145ee82","quote":"Teachers open the door, but you must enter by yourself.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Trung Hoa","status":"approved","meaning":"Thầy cô mở cửa, nhưng bạn phải tự mình bước vào.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3391bb1e-ba3d-4aa3-8694-bcf584adcc43","quote":"The best teachers are those who show you where to look but don't tell you what to see.","topic":"Học tập & Ngôn ngữ","author":"Alexandra K. Trenfor","status":"draft","meaning":"Người thầy giỏi nhất là người chỉ cho bạn nhìn vào đâu, chứ không bảo bạn phải thấy gì.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c455cce6-7c37-4fe9-9390-1015da4597e5","quote":"In learning you will teach, and in teaching you will learn.","topic":"Học tập & Ngôn ngữ","author":"Phil Collins","status":"draft","meaning":"Trong học có dạy, trong dạy có học.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a10bf551-a895-42b0-af76-3b1a76540dc4","quote":"Learning is a treasure that will follow its owner everywhere.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Trung Hoa","status":"approved","meaning":"Học vấn là kho báu theo chủ nhân đi khắp mọi nơi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7033248a-752a-4bc7-86de-174e8080f47c","quote":"To learn a language is to have one more window from which to look at the world.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Trung Hoa","status":"approved","meaning":"Học một ngôn ngữ là có thêm một khung cửa sổ để nhìn ra thế giới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"785db25b-2c64-4dd3-968f-9a650edf237a","quote":"The limits of my language mean the limits of my world.","topic":"Học tập & Ngôn ngữ","author":"Ludwig Wittgenstein","status":"approved","meaning":"Giới hạn ngôn ngữ của tôi là giới hạn thế giới của tôi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cf915982-69c5-4e28-ad0e-6b9a490c8dfc","quote":"One language sets you in a corridor for life. Two languages open every door along the way.","topic":"Học tập & Ngôn ngữ","author":"Frank Smith","status":"draft","meaning":"Một ngôn ngữ đặt bạn vào một hành lang suốt đời. Hai ngôn ngữ mở mọi cánh cửa dọc đường đi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"634cfda1-64cb-4ed5-b456-cbbb7b99fbd3","quote":"To have another language is to possess a second soul.","topic":"Học tập & Ngôn ngữ","author":"Charlemagne","status":"draft","meaning":"Biết thêm một ngôn ngữ là có thêm một linh hồn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fcbb6c8a-4f06-41d8-be2e-a58625eb84b6","quote":"Those who know nothing of foreign languages know nothing of their own.","topic":"Học tập & Ngôn ngữ","author":"Johann Wolfgang von Goethe","status":"approved","meaning":"Ai không biết gì về ngoại ngữ thì cũng không biết gì về ngôn ngữ của chính mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"85385906-e774-4b1c-8035-7b3ceb3335c0","quote":"A different language is a different vision of life.","topic":"Học tập & Ngôn ngữ","author":"Federico Fellini","status":"draft","meaning":"Một ngôn ngữ khác là một cách nhìn khác về cuộc sống.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dbb08c45-d6b6-4e56-b482-dcb9a009b0fb","quote":"Mistakes are the portals of discovery.","topic":"Học tập & Ngôn ngữ","author":"James Joyce","status":"approved","meaning":"Sai lầm là cánh cửa của khám phá.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"abdacac3-77f6-4f7f-b54f-854f8d2ca176","quote":"Experience is the teacher of all things.","topic":"Học tập & Ngôn ngữ","author":"Julius Caesar","status":"approved","meaning":"Kinh nghiệm là người thầy của mọi điều.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"12ffba58-ca2a-4d12-9707-4dc55b7bae2f","quote":"Experience is simply the name we give our mistakes.","topic":"Học tập & Ngôn ngữ","author":"Oscar Wilde","status":"approved","meaning":"Kinh nghiệm chỉ là cái tên ta đặt cho những sai lầm của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fe632a20-6306-4c92-8473-2845bcc78325","quote":"Knowledge speaks, but wisdom listens.","topic":"Học tập & Ngôn ngữ","author":"Jimi Hendrix","status":"draft","meaning":"Tri thức thì nói, còn trí tuệ thì lắng nghe.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"544907cc-0b3c-4b3c-91db-b5a34db74578","quote":"Any fool can know. The point is to understand.","topic":"Học tập & Ngôn ngữ","author":"Albert Einstein","status":"draft","meaning":"Kẻ ngốc nào cũng có thể biết. Điều quan trọng là hiểu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1b4ca1bf-395e-4663-a597-5287a77ae35b","quote":"Curiosity is the wick in the candle of learning.","topic":"Học tập & Ngôn ngữ","author":"William Arthur Ward","status":"draft","meaning":"Sự tò mò là bấc của ngọn nến học tập.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"74f73d49-203f-4d7e-8d9b-2727e24cabf5","quote":"He who asks a question is a fool for five minutes; he who does not ask remains a fool forever.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Trung Hoa","status":"approved","meaning":"Người hỏi chỉ ngốc trong năm phút; người không hỏi sẽ ngốc mãi mãi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1350af40-4cee-4060-8028-7c9727c95061","quote":"It is never too late to learn.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Anh","status":"approved","meaning":"Không bao giờ là quá muộn để học.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cf30e5f8-964b-42c1-9781-db6a3f9396c3","quote":"Practice makes perfect.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Anh","status":"approved","meaning":"Có luyện tập mới hoàn hảo.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"22f9be47-7129-4570-ba11-9d3ade31820c","quote":"I think, therefore I am.","topic":"Học tập & Ngôn ngữ","author":"René Descartes","status":"draft","meaning":"Tôi tư duy, nên tôi tồn tại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6e116ec6-0a0a-4f33-a09a-5f3aaa56943d","quote":"Learning from a teacher is not as good as learning from friends.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Học thầy không tày học bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"677d13dc-26f8-42b1-b1d5-9e03fe32fd52","quote":"However slow you are, study long enough and you will know.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Dốt đến đâu học lâu cũng biết.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6ef004f1-de83-4da3-9b3c-05f6a11d476e","quote":"What lies behind us and what lies before us are tiny matters compared to what lies within us.","topic":"Bản thân & Tự tin","author":"Henry S. Haskins","status":"draft","meaning":"Những gì phía sau và phía trước ta đều nhỏ bé so với những gì ở bên trong ta.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"63dd748c-03c3-40aa-9817-9ec188d81cfc","quote":"No one can make you feel inferior without your consent.","topic":"Bản thân & Tự tin","author":"Eleanor Roosevelt","status":"draft","meaning":"Không ai có thể khiến bạn cảm thấy thấp kém nếu không có sự cho phép của bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e3eb56b5-c08d-46f0-a065-11252e24eaa3","quote":"Do what you feel in your heart to be right, for you'll be criticized anyway.","topic":"Bản thân & Tự tin","author":"Eleanor Roosevelt","status":"draft","meaning":"Hãy làm điều trái tim bạn cho là đúng, vì đằng nào bạn cũng bị chỉ trích.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e446c492-d94a-4b2a-a6c3-7cea291eafbb","quote":"He who conquers himself is the mightiest warrior.","topic":"Bản thân & Tự tin","author":"Khổng Tử","status":"draft","meaning":"Người chiến thắng bản thân là chiến binh mạnh nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e2910581-5fa3-4aca-b9fc-29b3c775bb35","quote":"Care about what other people think and you will always be their prisoner.","topic":"Bản thân & Tự tin","author":"Lão Tử","status":"draft","meaning":"Bận tâm đến suy nghĩ của người khác, bạn sẽ mãi là tù nhân của họ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"da3a1290-e661-4bc0-b94b-c904329aba5f","quote":"It's not what happens to you, but how you react to it that matters.","topic":"Bản thân & Tự tin","author":"Epictetus","status":"draft","meaning":"Điều quan trọng không phải là chuyện gì xảy ra với bạn, mà là bạn phản ứng thế nào.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3bf68496-6f90-4b97-93b6-3e094c687e0c","quote":"Whatever the mind of man can conceive and believe, it can achieve.","topic":"Bản thân & Tự tin","author":"Napoleon Hill","status":"draft","meaning":"Bất cứ điều gì trí óc con người có thể hình dung và tin tưởng, nó đều có thể đạt được.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"36736ef0-5619-43b0-912b-84f5eefa9bc0","quote":"With confidence, you have won before you have started.","topic":"Bản thân & Tự tin","author":"Marcus Garvey","status":"approved","meaning":"Có tự tin, bạn đã chiến thắng trước khi bắt đầu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e28b097c-27d8-4f8e-811e-fb2d1212c3e9","quote":"Believe in yourself! Have faith in your abilities!","topic":"Bản thân & Tự tin","author":"Norman Vincent Peale","status":"draft","meaning":"Hãy tin vào chính mình! Hãy tin vào khả năng của bạn!","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d5f21715-cf82-4c49-93e6-a429a2eda87a","quote":"Our deepest fear is not that we are inadequate. Our deepest fear is that we are powerful beyond measure.","topic":"Bản thân & Tự tin","author":"Marianne Williamson","status":"draft","meaning":"Nỗi sợ sâu thẳm nhất của ta không phải là mình kém cỏi, mà là mình mạnh mẽ vượt ngoài mọi thước đo.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4311000a-a403-4114-a101-d07aafc347de","quote":"The privilege of a lifetime is to become who you truly are.","topic":"Bản thân & Tự tin","author":"Carl Jung","status":"draft","meaning":"Đặc ân của cả một đời là trở thành con người thật của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"60595681-e32b-4c1c-a2a4-8bab9b60a693","quote":"Who looks outside, dreams; who looks inside, awakes.","topic":"Bản thân & Tự tin","author":"Carl Jung","status":"draft","meaning":"Ai nhìn ra ngoài thì mơ, ai nhìn vào trong thì tỉnh thức.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0800f78b-27a2-4c7e-ac61-58f32120f3b4","quote":"Knowing your own darkness is the best method for dealing with the darknesses of other people.","topic":"Bản thân & Tự tin","author":"Carl Jung","status":"draft","meaning":"Hiểu bóng tối của chính mình là cách tốt nhất để đối diện với bóng tối của người khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"44ea7e5a-9640-4cf3-96ea-f537123a32f9","quote":"Owning our story and loving ourselves through that process is the bravest thing we'll ever do.","topic":"Bản thân & Tự tin","author":"Brené Brown","status":"draft","meaning":"Chấp nhận câu chuyện của mình và yêu thương bản thân qua quá trình ấy là điều dũng cảm nhất ta từng làm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"82929fb5-725f-41e0-9f93-3de498343cc1","quote":"Talk to yourself like you would to someone you love.","topic":"Bản thân & Tự tin","author":"Brené Brown","status":"draft","meaning":"Hãy nói chuyện với bản thân như cách bạn nói với người mình yêu thương.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3f4534df-3003-4722-93cc-32c323d53df1","quote":"Do not let what you cannot do interfere with what you can do.","topic":"Bản thân & Tự tin","author":"John Wooden","status":"draft","meaning":"Đừng để những gì bạn không làm được cản trở những gì bạn có thể làm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3d84a7a2-6c83-49e4-8b94-eaa0e22d93b6","quote":"Be more concerned with your character than your reputation, because your character is what you really are.","topic":"Bản thân & Tự tin","author":"John Wooden","status":"draft","meaning":"Hãy quan tâm đến nhân cách hơn danh tiếng, vì nhân cách mới là con người thật của bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e98bf37b-75aa-4fe5-abc4-4a17f09554c9","quote":"Do not compare yourself with others. Compare yourself with who you were yesterday.","topic":"Bản thân & Tự tin","author":"Jordan Peterson","status":"draft","meaning":"Đừng so sánh mình với người khác. Hãy so với chính mình của ngày hôm qua.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"37587a3d-5038-40ce-9b1e-eb771cf2d19b","quote":"Today you are You, that is truer than true. There is no one alive who is Youer than You.","topic":"Bản thân & Tự tin","author":"Dr. Seuss","status":"draft","meaning":"Hôm nay bạn là Bạn, điều đó thật hơn cả sự thật. Không ai trên đời Bạn hơn chính Bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"85a79373-9f65-4456-9970-a7e22c60c26a","quote":"The most common way people give up their power is by thinking they don't have any.","topic":"Bản thân & Tự tin","author":"Alice Walker","status":"draft","meaning":"Cách phổ biến nhất khiến con người từ bỏ sức mạnh là nghĩ rằng mình chẳng có chút sức mạnh nào.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dc53bc2e-edbb-430a-8ef5-494b2e4d5542","quote":"Confidence comes not from always being right but from not fearing to be wrong.","topic":"Bản thân & Tự tin","author":"Peter T. McIntyre","status":"draft","meaning":"Sự tự tin không đến từ việc luôn đúng, mà đến từ việc không sợ sai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b100d445-8511-47ab-b039-6ee95c0525ee","quote":"You have been criticizing yourself for years, and it hasn't worked. Try approving of yourself and see what happens.","topic":"Bản thân & Tự tin","author":"Louise Hay","status":"draft","meaning":"Bạn đã chỉ trích bản thân nhiều năm mà chẳng hiệu quả. Hãy thử chấp nhận bản thân và xem điều gì xảy ra.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5db3e9fe-f58c-4f72-8fa9-ea77f7261f5c","quote":"Self-care is not selfish. You cannot serve from an empty vessel.","topic":"Bản thân & Tự tin","author":"Eleanor Brown","status":"draft","meaning":"Chăm sóc bản thân không phải ích kỷ. Bạn không thể rót từ một chiếc bình rỗng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3dbef0fd-bf3d-48be-a94b-9e3cc5c88e30","quote":"Silence is a source of great strength.","topic":"Bản thân & Tự tin","author":"Lão Tử","status":"draft","meaning":"Im lặng là nguồn sức mạnh lớn lao.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3abcccd4-27ab-484d-b0fa-0f290f126a3a","quote":"The moment you think it's too late is actually the earliest time.","topic":"Không bao giờ là muộn","author":"Tục ngữ Hàn Quốc","status":"approved","meaning":"Lúc bạn nghĩ đã quá muộn chính là lúc sớm nhất để bắt đầu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3038bdaa-d19a-432f-a291-ee72a794bf16","quote":"Time and tide wait for no man.","topic":"Thời gian & Hiện tại","author":"Tục ngữ Anh","status":"draft","meaning":"Thời gian và thủy triều không chờ đợi ai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b4efec6f-3b1d-447f-ac61-0f94496ebaf7","quote":"Heaven does not fail those who try.","topic":"Từng bước nhỏ","author":"Tục ngữ Việt Nam","status":"approved","meaning":"Trời không phụ lòng người.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fdf84543-0d28-426e-ac14-7b3d62d69476","quote":"Slow but sure.","topic":"Từng bước nhỏ","author":"Thành ngữ Việt Nam","status":"approved","meaning":"Chậm mà chắc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d8a72c7d-e88b-4da2-a8b6-858481d50efa","quote":"No great thing is created suddenly.","topic":"Từng bước nhỏ","author":"Epictetus","status":"approved","meaning":"Không điều gì vĩ đại được tạo ra trong chốc lát.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7f6cde91-f04f-40cb-b9ed-5f7b128b2698","quote":"Everything comes in time to those who know how to wait.","topic":"Từng bước nhỏ","author":"Tục ngữ Pháp","status":"approved","meaning":"Mọi điều tốt đẹp đến đúng lúc với người biết chờ đợi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0a3bea46-6cd5-4b0b-82c8-15ff6b12d1de","quote":"Be patient and you will attain.","topic":"Từng bước nhỏ","author":"Tục ngữ Ả Rập","status":"approved","meaning":"Hãy kiên nhẫn, rồi bạn sẽ đạt được.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8c4560e9-4be2-4d2b-a84f-a9aa851c1493","quote":"Tomorrow is always fresh, with no mistakes in it yet.","topic":"Không bao giờ là muộn","author":"L. M. Montgomery","status":"approved","meaning":"Ngày mai luôn mới tinh, chưa có lỗi lầm nào cả.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1fdddbf5-483b-4b72-8498-143c8fdb4814","quote":"Nothing is worth more than this day.","topic":"Không bao giờ là muộn","author":"Johann Wolfgang von Goethe","status":"approved","meaning":"Không gì đáng giá hơn ngày hôm nay.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"31005f6b-1bd7-48d8-a1af-5c6b5bd90fbc","quote":"Language is the blood of the soul into which thoughts run and out of which they grow.","topic":"Học ngoại ngữ","author":"Oliver Wendell Holmes Sr.","status":"draft","meaning":"Ngôn ngữ là dòng máu của tâm hồn, nơi suy nghĩ chảy vào và từ đó lớn lên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"13fb5cf0-c56f-4ed2-94f6-f017a75e03ae","quote":"Language is the dress of thought.","topic":"Học ngoại ngữ","author":"Samuel Johnson","status":"draft","meaning":"Ngôn ngữ là tấm áo của tư tưởng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a15c1d16-983c-4014-84a4-55c51d4cef51","quote":"Not hearing is not as good as hearing; hearing is not as good as seeing; seeing is not as good as knowing; knowing is not as good as doing. Learning reaches its end in doing.","topic":"Học ngoại ngữ","author":"Tuân Tử","status":"draft","meaning":"Không nghe không bằng nghe, nghe không bằng thấy, thấy không bằng hiểu, hiểu không bằng làm; học đến khi làm được mới là trọn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"618894c7-067c-43a9-9337-4b5a973988f6","quote":"A man who speaks two languages is worth two men.","topic":"Học ngoại ngữ","author":"Tục ngữ Pháp","status":"draft","meaning":"Người biết hai ngôn ngữ đáng giá bằng hai người.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5af07c25-c585-4d21-bea7-8110865a4f53","quote":"Language is wine upon the lips.","topic":"Học ngoại ngữ","author":"Virginia Woolf","status":"draft","meaning":"Ngôn ngữ là rượu vang trên môi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ea9d63cb-5b61-4b6f-b091-05ebe3503e3f","quote":"Language is a city to the building of which every human being brought a stone.","topic":"Học ngoại ngữ","author":"Ralph Waldo Emerson","status":"draft","meaning":"Ngôn ngữ là một thành phố mà mỗi con người đều góp một viên đá để xây nên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b57783e6-6e6a-4247-9cad-86078a3116f4","quote":"The spirit of a language reveals itself most clearly in its untranslatable words.","topic":"Học ngoại ngữ","author":"Marie von Ebner-Eschenbach","status":"draft","meaning":"Tinh thần của một ngôn ngữ hiện rõ nhất ở những từ không thể dịch được.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"51c67f1d-49fd-474a-8998-6fc39eb0b101","quote":"Every language is a temple, in which the soul of those who speak it is enshrined.","topic":"Học ngoại ngữ","author":"Oliver Wendell Holmes Sr.","status":"draft","meaning":"Mỗi ngôn ngữ là một ngôi đền, nơi tâm hồn của người nói nó được tôn thờ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"407de4df-1a48-4511-a6d3-0b94dde80485","quote":"The diversity of languages is not a diversity of sounds and signs, but a diversity of views of the world.","topic":"Học ngoại ngữ","author":"Wilhelm von Humboldt","status":"draft","meaning":"Sự đa dạng của ngôn ngữ không phải là đa dạng âm thanh và ký hiệu, mà là đa dạng cách nhìn thế giới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"647201df-6f0b-42e3-a992-447353fc5165","quote":"Language is the archives of history.","topic":"Học ngoại ngữ","author":"Ralph Waldo Emerson","status":"draft","meaning":"Ngôn ngữ là kho lưu trữ của lịch sử.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a53a6cc6-b6ac-4d0f-b2bf-21e5d1d6cd84","quote":"No man should travel until he has learned the language of the country he visits. Otherwise he voluntarily makes himself a great baby, so helpless and so ridiculous.","topic":"Học ngoại ngữ","author":"Ralph Waldo Emerson","status":"draft","meaning":"Đừng ai đi du lịch khi chưa học ngôn ngữ của đất nước mình đến. Bằng không, họ tự biến mình thành một đứa trẻ lớn xác, bất lực và buồn cười.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9c252dfe-de00-4a06-9507-3bafc780e2a4","quote":"I am always sorry when any language is lost, because languages are the pedigrees of nations.","topic":"Học ngoại ngữ","author":"Samuel Johnson","status":"draft","meaning":"Tôi luôn tiếc khi có một ngôn ngữ biến mất, vì ngôn ngữ là gia phả của các dân tộc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"244fb281-7303-453d-aee5-13d9ec05ea84","quote":"No two languages are ever sufficiently similar to be considered as representing the same social reality.","topic":"Học ngoại ngữ","author":"Edward Sapir","status":"draft","meaning":"Không có hai ngôn ngữ nào đủ giống nhau để được xem là phản ánh cùng một thực tại xã hội.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b2501be5-b2e4-42fc-b8fa-f60a0d2013c7","quote":"Old donkeys don't learn languages.","topic":"Học ngoại ngữ","author":"Tục ngữ Bồ Đào Nha","status":"draft","meaning":"Lừa già không học được ngôn ngữ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b4e0d23c-052b-4990-8135-cd2dbd5afa5a","quote":"Whoever wants to have an effect on others must first speak with them in their language.","topic":"Học ngoại ngữ","author":"Kurt Tucholsky","status":"draft","meaning":"Ai muốn tác động đến người khác thì trước hết phải nói với họ bằng ngôn ngữ của họ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2bbacba3-b9e2-432e-ac01-260807968157","quote":"Languages are not strangers to one another.","topic":"Học ngoại ngữ","author":"Walter Benjamin","status":"draft","meaning":"Các ngôn ngữ không xa lạ với nhau.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7fbdb87d-fe5e-4139-8034-f4b24f09fa2e","quote":"But if thought corrupts language, language can also corrupt thought.","topic":"Học ngoại ngữ","author":"George Orwell","status":"draft","meaning":"Nếu tư duy làm hỏng ngôn ngữ, thì ngôn ngữ cũng có thể làm hỏng tư duy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4ede4df1-4969-40d4-89ba-133d84a8e394","quote":"In language, it is simply required that it convey the meaning.","topic":"Học ngoại ngữ","author":"Khổng Tử","status":"draft","meaning":"Lời nói, chỉ cần truyền đạt được ý là đủ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0200092b-bcc5-4928-bcf0-1989e503f419","quote":"Language is the mother of thought, not its handmaiden.","topic":"Học ngoại ngữ","author":"Karl Kraus","status":"draft","meaning":"Ngôn ngữ là mẹ của tư duy, không phải người hầu của nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e70a7d9c-a1f1-49b3-b8e1-e3e7f8260206","quote":"Humour is the first of the gifts to perish in a foreign tongue.","topic":"Học ngoại ngữ","author":"Virginia Woolf","status":"draft","meaning":"Sự hài hước là món quà đầu tiên mất đi trong một ngôn ngữ xa lạ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a7214c6b-0c4b-4426-8ae6-2f82aac7a5f3","quote":"What doesn't kill me makes me stronger.","topic":"Nghị lực & Vượt khó","author":"Friedrich Nietzsche","status":"draft","meaning":"Điều gì không giết được ta sẽ khiến ta mạnh mẽ hơn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"eaf08530-5f49-49e4-be8d-ae065063d4bf","quote":"The impediment to action advances action. What stands in the way becomes the way.","topic":"Nghị lực & Vượt khó","author":"Marcus Aurelius","status":"draft","meaning":"Chướng ngại cản trở hành động lại thúc đẩy hành động. Thứ cản đường trở thành con đường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"898e48ec-4fc7-40cb-969f-11049fb7e2e6","quote":"Fire is the test of gold; adversity, of strong men.","topic":"Nghị lực & Vượt khó","author":"Seneca","status":"draft","meaning":"Lửa thử vàng, gian nan thử sức người mạnh mẽ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ba042641-bf0a-43f4-b7c6-c2ab7a7a75dd","quote":"Patience and perseverance have a magical effect before which difficulties disappear and obstacles vanish.","topic":"Nghị lực & Vượt khó","author":"John Quincy Adams","status":"draft","meaning":"Kiên nhẫn và bền bỉ có một sức mạnh kỳ diệu khiến khó khăn tan biến và chướng ngại biến mất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"940e625e-75e2-4459-86dc-0ed4365a493a","quote":"Nothing in the world is softer than water, yet nothing is better at overcoming the hard and strong.","topic":"Nghị lực & Vượt khó","author":"Lão Tử","status":"draft","meaning":"Không gì trên đời mềm yếu hơn nước, vậy mà không gì thắng được cái cứng rắn bằng nước.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2930ebcc-ba7e-4838-bf49-3e9ed307750e","quote":"Hope is the thing with feathers that perches in the soul.","topic":"Nghị lực & Vượt khó","author":"Emily Dickinson","status":"draft","meaning":"Hy vọng là thứ có lông vũ, đậu trên tâm hồn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a23e4b31-cf4e-4046-b0fd-6b1dcc35a271","quote":"Strength does not come from physical capacity. It comes from an indomitable will.","topic":"Nghị lực & Vượt khó","author":"Mahatma Gandhi","status":"draft","meaning":"Sức mạnh không đến từ thể chất, mà đến từ ý chí bất khuất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a237a197-b411-4109-b71c-b8aacd8aad76","quote":"Through perseverance many people win success out of what seemed destined to be certain failure.","topic":"Nghị lực & Vượt khó","author":"Benjamin Disraeli","status":"draft","meaning":"Nhờ kiên trì, nhiều người đã giành được thành công từ điều tưởng chừng chắc chắn thất bại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8e1b22a5-a7d8-48e8-b3c4-58d366b4077c","quote":"The harder the conflict, the more glorious the triumph.","topic":"Nghị lực & Vượt khó","author":"Thomas Paine","status":"draft","meaning":"Cuộc chiến càng gian nan, chiến thắng càng vẻ vang.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"eb6c38d2-21e9-4d45-b142-379922fc0a0e","quote":"Persistence guarantees that results are inevitable.","topic":"Nghị lực & Vượt khó","author":"Paramahansa Yogananda","status":"draft","meaning":"Sự bền bỉ đảm bảo kết quả là điều tất yếu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0cdf9a3c-10f9-40f8-ab1e-93593a32fcc1","quote":"Let me tell you the secret that has led me to my goal. My strength lies solely in my tenacity.","topic":"Nghị lực & Vượt khó","author":"Louis Pasteur","status":"draft","meaning":"Hãy để tôi kể bí mật đã đưa tôi đến mục tiêu: sức mạnh của tôi nằm ở sự bền bỉ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6197a87d-d79a-4ce9-8556-adc56a6ed4a5","quote":"Adversity is the first path to truth.","topic":"Nghị lực & Vượt khó","author":"Lord Byron","status":"draft","meaning":"Nghịch cảnh là con đường đầu tiên dẫn tới chân lý.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"51bb20ee-929e-417a-8d23-2386003ce723","quote":"Calamity is the test of integrity.","topic":"Nghị lực & Vượt khó","author":"Samuel Richardson","status":"draft","meaning":"Tai họa là phép thử của sự chính trực.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0552986f-65ed-4faa-aaa3-d0c26b2f0d82","quote":"Lost time is never found again.","topic":"Thành công & Hành động","author":"Benjamin Franklin","status":"draft","meaning":"Thời gian đã mất thì không bao giờ tìm lại được.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fdfe93cd-a0c5-4a1b-b927-370c34cfbd13","quote":"It is not the critic who counts; the credit belongs to the man who is actually in the arena.","topic":"Thành công & Hành động","author":"Theodore Roosevelt","status":"draft","meaning":"Kẻ phê bình không quan trọng; vinh dự thuộc về người thực sự bước vào đấu trường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ba700a7c-e8fa-42ed-a65b-f1cd4c0969fc","quote":"Try not to become a man of success, but rather try to become a man of value.","topic":"Thành công & Hành động","author":"Albert Einstein","status":"draft","meaning":"Đừng cố trở thành người thành công, hãy cố trở thành người có giá trị.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"947dc0e0-5fad-4bf5-a5d9-36fb472cad1a","quote":"The superior man is modest in his speech, but exceeds in his actions.","topic":"Thành công & Hành động","author":"Khổng Tử","status":"draft","meaning":"Người quân tử khiêm tốn trong lời nói nhưng vượt trội trong hành động.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d53f3ecd-6517-482b-ae11-62e3a119acbb","quote":"To know what is right and not do it is the worst cowardice.","topic":"Thành công & Hành động","author":"Khổng Tử","status":"draft","meaning":"Biết điều đúng mà không làm là hèn nhát nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"83e7368a-1d2d-4501-8c1c-27820e3e9776","quote":"He who knows others is wise; he who knows himself is enlightened.","topic":"Thành công & Hành động","author":"Lão Tử","status":"draft","meaning":"Biết người là trí, biết mình là sáng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c71835c0-1e90-41d5-96de-90dab565cc61","quote":"Know your enemy and know yourself, and you can fight a hundred battles without disaster.","topic":"Thành công & Hành động","author":"Tôn Tử","status":"draft","meaning":"Biết người biết ta, trăm trận không nguy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"233bd32f-3aa9-468b-b866-4d679b79dc43","quote":"I dream my painting and I paint my dream.","topic":"Thành công & Hành động","author":"Vincent van Gogh","status":"draft","meaning":"Tôi mơ về bức tranh và tôi vẽ giấc mơ của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0c39807c-8f45-48b2-9728-928d9a3fc319","quote":"Bamboo shoots grow in seasons; people have their time.","topic":"Thành công & Hành động","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Măng mọc có lứa, người ta có thì.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a5827177-0e9b-427e-bbdc-7c746fc52083","quote":"Working hands feed the mouth; idle hands leave it hungry.","topic":"Thành công & Hành động","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Tay làm hàm nhai, tay quai miệng trễ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b8f265c6-42cc-49f1-8344-9e653f4f8481","quote":"People make the plans; heaven decides the outcome.","topic":"Thành công & Hành động","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Mưu sự tại nhân, thành sự tại thiên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fd4f0e43-c58e-43f4-8bd1-bb20452089a5","quote":"Time is the most valuable thing a man can spend.","topic":"Thời gian & Hiện tại","author":"Theophrastus","status":"draft","meaning":"Thời gian là thứ quý giá nhất mà con người có thể tiêu dùng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cfdb9562-047a-4d1e-b131-ae0423a15258","quote":"Time is what we want most, but what we use worst.","topic":"Thời gian & Hiện tại","author":"William Penn","status":"draft","meaning":"Thời gian là thứ ta muốn nhất, nhưng lại sử dụng tệ nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f27781b8-2edb-4ff2-9437-8e9fb0fe5f58","quote":"Dost thou love life? Then do not squander time, for that's the stuff life is made of.","topic":"Thời gian & Hiện tại","author":"Benjamin Franklin","status":"draft","meaning":"Bạn có yêu cuộc sống không? Vậy đừng phung phí thời gian, vì cuộc sống được làm nên từ nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1af83406-1259-4bba-a56d-4d9fdc2e2961","quote":"Time is money.","topic":"Thời gian & Hiện tại","author":"Benjamin Franklin","status":"draft","meaning":"Thời gian là tiền bạc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"96281d60-f368-4c14-ba51-2a1c97a2fdc3","quote":"The two most powerful warriors are patience and time.","topic":"Thời gian & Hiện tại","author":"Leo Tolstoy","status":"draft","meaning":"Hai chiến binh mạnh nhất là kiên nhẫn và thời gian.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c0b21198-dae2-45af-8d9f-af3b84f4ac2f","quote":"Procrastination is the thief of time.","topic":"Thời gian & Hiện tại","author":"Edward Young","status":"draft","meaning":"Trì hoãn là kẻ trộm thời gian.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7ef5112f-b899-417b-81ae-9df2267ca2df","quote":"You may delay, but time will not.","topic":"Thời gian & Hiện tại","author":"Benjamin Franklin","status":"draft","meaning":"Bạn có thể trì hoãn, nhưng thời gian thì không.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"09c9ba6c-4000-49e1-8574-94c4fd62daa4","quote":"Never leave that till tomorrow which you can do today.","topic":"Thời gian & Hiện tại","author":"Benjamin Franklin","status":"draft","meaning":"Đừng để đến ngày mai việc bạn có thể làm hôm nay.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cbd470b9-54d9-4146-b2ce-d066bbb3f357","quote":"Nothing is so dear and precious as time.","topic":"Thời gian & Hiện tại","author":"François Rabelais","status":"draft","meaning":"Không gì quý báu bằng thời gian.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"86c4de3a-5d3b-491e-ae10-d319e0987cc9","quote":"Time flies over us, but leaves its shadow behind.","topic":"Thời gian & Hiện tại","author":"Nathaniel Hawthorne","status":"draft","meaning":"Thời gian bay qua ta, nhưng để lại bóng hình phía sau.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"abc12041-4124-4055-a4a8-f9eb06420fc4","quote":"Time discovers truth.","topic":"Thời gian & Hiện tại","author":"Seneca","status":"draft","meaning":"Thời gian sẽ làm lộ ra sự thật.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"82dd9598-5632-4f0e-886c-021b6a7a73ee","quote":"Hold every hour in your grasp. Lean less on tomorrow if you seize today.","topic":"Thời gian & Hiện tại","author":"Seneca","status":"draft","meaning":"Hãy nắm chặt từng giờ. Nắm lấy hôm nay thì bạn sẽ ít phải dựa vào ngày mai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"81e9644e-e764-49f0-ac08-ac75f09e3bb6","quote":"Everything flows, nothing stays still.","topic":"Thời gian & Hiện tại","author":"Heraclitus","status":"draft","meaning":"Vạn vật trôi chảy, không gì đứng yên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4896d07c-4c1a-439e-b263-0339b753f791","quote":"Time is a river of passing events, and strong is its current.","topic":"Thời gian & Hiện tại","author":"Marcus Aurelius","status":"draft","meaning":"Thời gian là dòng sông của những sự kiện trôi qua, và dòng chảy của nó rất mạnh.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e97219e0-9dfd-401d-a5ae-e6151f2e6f1f","quote":"Confine yourself to the present.","topic":"Thời gian & Hiện tại","author":"Marcus Aurelius","status":"draft","meaning":"Hãy giới hạn bản thân trong hiện tại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"486bd695-98fe-4d6c-85c5-39a1bb3fbc99","quote":"Seize the day, putting as little trust as possible in tomorrow.","topic":"Thời gian & Hiện tại","author":"Horace","status":"draft","meaning":"Hãy nắm lấy ngày hôm nay, và tin vào ngày mai càng ít càng tốt.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7ba6d900-887e-4dab-8795-9ae6a9503e10","quote":"Carpe diem.","topic":"Thời gian & Hiện tại","author":"Horace","status":"draft","meaning":"Hãy nắm bắt ngày hôm nay.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fe2a1e84-c0e7-4f89-8aae-5b5f9e253552","quote":"While we are speaking, envious time will have fled.","topic":"Thời gian & Hiện tại","author":"Horace","status":"draft","meaning":"Trong lúc ta đang nói, thời gian ganh tị đã trôi mất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b3c2aec2-2a19-46b2-9dcd-e39d7f2ebbc2","quote":"Time is the wisest counselor of all.","topic":"Thời gian & Hiện tại","author":"Pericles","status":"draft","meaning":"Thời gian là người cố vấn khôn ngoan nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c79af24d-617f-41a1-82ce-74708719d942","quote":"I wasted time, and now doth time waste me.","topic":"Thời gian & Hiện tại","author":"William Shakespeare","status":"draft","meaning":"Ta đã lãng phí thời gian, và giờ thời gian đang lãng phí ta.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"976429c0-c5d9-4683-b7b8-c92612deaabc","quote":"Better three hours too soon than a minute too late.","topic":"Thời gian & Hiện tại","author":"William Shakespeare","status":"draft","meaning":"Thà sớm ba tiếng còn hơn trễ một phút.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ef7d218d-5618-4fdb-b162-53aa850ce718","quote":"Write it on your heart that every day is the best day in the year.","topic":"Thời gian & Hiện tại","author":"Ralph Waldo Emerson","status":"draft","meaning":"Hãy khắc vào tim rằng mỗi ngày đều là ngày tuyệt nhất trong năm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"acb1f6ba-9d62-4600-8b54-d2f4df37818c","quote":"Finish each day and be done with it.","topic":"Thời gian & Hiện tại","author":"Ralph Waldo Emerson","status":"draft","meaning":"Hãy hoàn tất mỗi ngày và khép lại nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"90779320-220c-459c-9766-4537e3ccd0ea","quote":"A man who dares to waste one hour of time has not discovered the value of life.","topic":"Thời gian & Hiện tại","author":"Charles Darwin","status":"draft","meaning":"Người dám lãng phí một giờ là người chưa khám phá ra giá trị của cuộc sống.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b5033102-a4fe-41be-800a-5d2ff2e34202","quote":"Wrinkles should merely indicate where smiles have been.","topic":"Thời gian & Hiện tại","author":"Mark Twain","status":"draft","meaning":"Nếp nhăn chỉ nên là dấu vết của những nụ cười đã qua.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f95f41a5-65b2-40af-ba2b-7683c578dc7f","quote":"Time is gold and silver.","topic":"Thời gian & Hiện tại","author":"Thành ngữ Việt Nam","status":"draft","meaning":"Thời gian là vàng bạc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"147a7484-4142-4480-be09-36956aa03fcf","quote":"An inch of time is an inch of gold, but an inch of gold cannot buy an inch of time.","topic":"Thời gian & Hiện tại","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Một tấc thời gian là một tấc vàng, tấc vàng khó mua được tấc thời gian.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6b6b8cdc-72ed-44d5-a6f1-8b746b2280c7","quote":"Like a horse's shadow flashing past a window (time flies).","topic":"Thời gian & Hiện tại","author":"Thành ngữ Việt Nam","status":"draft","meaning":"Bóng câu qua cửa sổ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dab1ba3b-ab26-437c-941f-49b267c63687","quote":"Don't leave today's work for tomorrow.","topic":"Thời gian & Hiện tại","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Việc hôm nay chớ để ngày mai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"907715f5-c723-4da6-8c9d-76c0ea1951ef","quote":"Learning without thought is labor lost; thought without learning is perilous.","topic":"Học tập & Ngôn ngữ","author":"Khổng Tử","status":"draft","meaning":"Học mà không nghĩ thì uổng công; nghĩ mà không học thì nguy hiểm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cd933874-f216-493e-bd59-f6b43b9f8eb7","quote":"To know what you know and what you do not know, that is true knowledge.","topic":"Học tập & Ngôn ngữ","author":"Khổng Tử","status":"draft","meaning":"Biết thì nói là biết, không biết thì nói là không biết, đó mới thật là biết.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b74cdfa7-9439-4fad-be1a-5281ceae309a","quote":"Knowledge is power.","topic":"Học tập & Ngôn ngữ","author":"Francis Bacon","status":"draft","meaning":"Tri thức là sức mạnh.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"01293280-f4ab-4163-b949-daf9ce0fa8d7","quote":"Reading maketh a full man; conference a ready man; and writing an exact man.","topic":"Học tập & Ngôn ngữ","author":"Francis Bacon","status":"draft","meaning":"Đọc làm con người đầy đủ, trò chuyện làm con người nhanh nhạy, viết làm con người chính xác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c59528e5-5f5e-4223-93e5-e04f8e027087","quote":"Some books are to be tasted, others to be swallowed, and some few to be chewed and digested.","topic":"Học tập & Ngôn ngữ","author":"Francis Bacon","status":"draft","meaning":"Có sách chỉ để nếm, có sách để nuốt, và một số ít cần nhai kỹ và tiêu hóa.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"efc1c374-42d1-4a74-9c87-66d05c96f4c0","quote":"Imagination is more important than knowledge.","topic":"Học tập & Ngôn ngữ","author":"Albert Einstein","status":"draft","meaning":"Trí tưởng tượng quan trọng hơn tri thức.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a10b9845-25fd-4c0c-8543-dbbe763868c9","quote":"Wisdom is not a product of schooling but of the lifelong attempt to acquire it.","topic":"Học tập & Ngôn ngữ","author":"Albert Einstein","status":"draft","meaning":"Trí tuệ không phải sản phẩm của trường lớp, mà của nỗ lực cả đời để đạt được nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9819f34d-2589-4443-a589-203e07694f51","quote":"Study without desire spoils the memory, and it retains nothing that it takes in.","topic":"Học tập & Ngôn ngữ","author":"Leonardo da Vinci","status":"draft","meaning":"Học mà không có khát khao sẽ làm hỏng trí nhớ, chẳng giữ lại được gì.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"29f0774f-b866-492d-91be-b8e4a40af9f9","quote":"If you have a garden and a library, you have everything you need.","topic":"Học tập & Ngôn ngữ","author":"Cicero","status":"draft","meaning":"Nếu bạn có một khu vườn và một thư viện, bạn có mọi thứ mình cần.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fd3fb49c-3859-428c-a55f-a57493bc5101","quote":"Learn, learn more, learn forever.","topic":"Học tập & Ngôn ngữ","author":"Vladimir Lenin","status":"draft","meaning":"Học, học nữa, học mãi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d423580c-308e-413e-ab98-18c16b12c91b","quote":"The reading of all good books is like a conversation with the finest minds of past centuries.","topic":"Học tập & Ngôn ngữ","author":"René Descartes","status":"draft","meaning":"Đọc mọi cuốn sách hay giống như trò chuyện với những trí tuệ ưu tú nhất của các thế kỷ trước.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"62ea7977-8a06-4f12-9573-758748b5555c","quote":"Once you learn to read, you will be forever free.","topic":"Học tập & Ngôn ngữ","author":"Frederick Douglass","status":"draft","meaning":"Một khi đã biết đọc, bạn sẽ được tự do mãi mãi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9c979f5b-4dae-4feb-bf2d-9665183ca674","quote":"Today a reader, tomorrow a leader.","topic":"Học tập & Ngôn ngữ","author":"Margaret Fuller","status":"draft","meaning":"Hôm nay là người đọc, ngày mai là người dẫn đầu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"976754fb-8bbe-4943-8937-5ec833ede6c6","quote":"Learning is not attained by chance, it must be sought for with ardor and attended to with diligence.","topic":"Học tập & Ngôn ngữ","author":"Abigail Adams","status":"draft","meaning":"Việc học không đến một cách tình cờ, nó phải được tìm kiếm nhiệt thành và chăm chỉ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ac58813a-f0ee-4ea3-a7ae-6756ded241a8","quote":"A teacher affects eternity; he can never tell where his influence stops.","topic":"Học tập & Ngôn ngữ","author":"Henry Adams","status":"draft","meaning":"Người thầy ảnh hưởng tới vĩnh cửu; không ai biết ảnh hưởng ấy dừng lại ở đâu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6c3d8180-9a2b-460c-90cf-cd249e38414a","quote":"Ask the experienced rather than the learned.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Ả Rập","status":"draft","meaning":"Hãy hỏi người có kinh nghiệm hơn là người có học.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1fc0ef04-1149-47f8-9657-fdf90b4610ce","quote":"To cross, build a bridge; for your child to be learned, love the teacher.","topic":"Học tập & Ngôn ngữ","author":"Ca dao Việt Nam","status":"draft","meaning":"Muốn sang thì bắc cầu kiều, muốn con hay chữ thì yêu lấy thầy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c11b423e-568d-47f8-a5ff-793eb6e129dc","quote":"Jade unpolished won't shine; people unschooled won't be wise.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Ngọc không mài không sáng, người không học không khôn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8f6c9ff8-7b5c-4af8-8454-6065873d52a1","quote":"Learn to eat, learn to speak, learn to wrap, learn to unwrap.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Học ăn, học nói, học gói, học mở.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"49edfbe0-4eda-4ebb-98ee-2debc450029e","quote":"First learn manners, then learn letters.","topic":"Học tập & Ngôn ngữ","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Tiên học lễ, hậu học văn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6c81940d-2d3e-4725-9d31-0b8b9ff19b67","quote":"Talented and virtuous people are the vital energy of a nation.","topic":"Học tập & Ngôn ngữ","author":"Thân Nhân Trung","status":"draft","meaning":"Hiền tài là nguyên khí của quốc gia.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"87e6aa06-dd98-49c0-a8aa-7ee4b3125486","quote":"As long as you live, keep learning how to live.","topic":"Không bao giờ là muộn","author":"Seneca","status":"approved","meaning":"Còn sống ngày nào, hãy còn học cách sống ngày ấy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"727fd579-6276-4c9d-afb4-048e807172f3","quote":"Speak if you know; if not, lean on the pillar and listen.","topic":"Học tập & Ngôn ngữ","author":"Ca dao Việt Nam","status":"draft","meaning":"Biết thì thưa thốt, không biết thì dựa cột mà nghe.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"601fd0d9-26d8-483a-90f0-0ab54d92d5a1","quote":"Know thyself.","topic":"Bản thân & Tự tin","author":"Châm ngôn Delphi","status":"draft","meaning":"Hãy biết chính mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9e03613f-f3d8-43bf-a66c-53173cfdf343","quote":"To thine own self be true.","topic":"Bản thân & Tự tin","author":"William Shakespeare","status":"draft","meaning":"Hãy sống thật với chính mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7ccb2797-ae6d-4f74-8c04-e9523b689479","quote":"Trust thyself: every heart vibrates to that iron string.","topic":"Bản thân & Tự tin","author":"Ralph Waldo Emerson","status":"draft","meaning":"Hãy tin vào chính mình: mọi trái tim đều rung lên theo sợi dây sắt ấy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"49693c7f-1980-47d0-9e53-e9c28d523c08","quote":"Self-trust is the first secret of success.","topic":"Bản thân & Tự tin","author":"Ralph Waldo Emerson","status":"draft","meaning":"Tin vào bản thân là bí quyết đầu tiên của thành công.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1ff90d49-57cb-4e44-9702-35485c84b3d9","quote":"Nothing can bring you peace but yourself.","topic":"Bản thân & Tự tin","author":"Ralph Waldo Emerson","status":"draft","meaning":"Không gì mang lại bình yên cho bạn ngoài chính bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2758bea6-6043-4511-add9-835a711b04e5","quote":"Mastering others is strength; mastering yourself is true power.","topic":"Bản thân & Tự tin","author":"Lão Tử","status":"draft","meaning":"Thắng người là có sức mạnh, thắng mình mới là thật sự hùng mạnh.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b71d3ea0-0568-4f27-91ad-d9ccebcbe728","quote":"All that we are is the result of what we have thought.","topic":"Bản thân & Tự tin","author":"Đức Phật","status":"draft","meaning":"Tất cả những gì ta là đều là kết quả của những gì ta đã nghĩ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cfa3f543-14ff-403e-a195-38e51f8383f5","quote":"You have power over your mind, not outside events. Realize this, and you will find strength.","topic":"Bản thân & Tự tin","author":"Marcus Aurelius","status":"draft","meaning":"Bạn có quyền làm chủ tâm trí mình, không phải các sự kiện bên ngoài. Hiểu điều này, bạn sẽ tìm thấy sức mạnh.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"446848e6-b33b-4f5f-bc0c-a1ee1c8e1054","quote":"Look within. Within is the fountain of good.","topic":"Bản thân & Tự tin","author":"Marcus Aurelius","status":"draft","meaning":"Hãy nhìn vào bên trong. Bên trong là suối nguồn của điều thiện.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"05afbcc4-834a-48a1-8633-53c5ec8bc157","quote":"You still have time. No one is timing your dreams.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn vẫn còn kịp. Không có ai bấm giờ cho ước mơ của bạn cả.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"64393df2-1596-43d3-aef8-96c478238161","quote":"No man is free who is not master of himself.","topic":"Bản thân & Tự tin","author":"Epictetus","status":"draft","meaning":"Không ai tự do nếu không làm chủ được bản thân.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0879f68b-359f-47c9-8e10-886f393e966c","quote":"First say to yourself what you would be; and then do what you have to do.","topic":"Bản thân & Tự tin","author":"Epictetus","status":"draft","meaning":"Trước hết hãy nói với mình bạn muốn trở thành ai; rồi làm những gì cần làm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f6ef62cd-0dcf-4a8c-a9e1-1d338a597e43","quote":"Man is not worried by real problems so much as by his imagined anxieties about real problems.","topic":"Bản thân & Tự tin","author":"Epictetus","status":"draft","meaning":"Con người không lo lắng vì vấn đề thực sự bằng vì những nỗi lo tưởng tượng về vấn đề ấy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fedf74f5-a2d0-40e7-9c91-c44d38b188ce","quote":"We suffer more often in imagination than in reality.","topic":"Bản thân & Tự tin","author":"Seneca","status":"draft","meaning":"Ta thường khổ sở trong tưởng tượng nhiều hơn ngoài thực tế.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"65154b0a-75e2-44d3-9251-92817e165c6f","quote":"Associate with people who are likely to improve you.","topic":"Bản thân & Tự tin","author":"Seneca","status":"draft","meaning":"Hãy gắn bó với những người có thể giúp bạn tốt hơn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ced7a34d-9ea6-4c8b-bfbb-a630f9cdfe93","quote":"Arriving a little late is fine; what matters is you got there on your own feet.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Muộn một chút không sao, quan trọng là bạn đến bằng chính đôi chân của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0a096be3-7e12-4c5f-a7cf-904a7ad2eff6","quote":"There's no age too late to learn something new and become someone new.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Không có độ tuổi nào là quá muộn để học một điều mới và trở thành một người mới.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1260ce10-28b0-43fa-ab14-86dc7875fe26","quote":"If you start today, you're already ahead of yesterday's you.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Hôm nay bạn bắt đầu, nghĩa là bạn đã đi trước phiên bản của mình ngày hôm qua.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"81d01ecc-cbea-4255-8a15-a09dc894dd19","quote":"Life isn't a race with one finish line. Everyone arrives in a different season.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Cuộc đời không phải đường đua có vạch đích chung. Mỗi người về đích ở một mùa khác nhau.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3073992f-081b-4650-b870-a496047c9f73","quote":"You haven't failed; your story just hasn't reached the best part yet.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn chưa thất bại, câu chuyện của bạn chỉ chưa đến đoạn hay nhất thôi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"21e34862-d42e-4d4a-acf9-c13f0e8e7b56","quote":"Don't say \"if only I'd started earlier.\" Say \"I'm glad I started.\"","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Đừng nói \"giá như mình bắt đầu sớm hơn\". Hãy nói \"may mà mình đã bắt đầu\".","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"976539b5-0147-483b-adea-843ba8a0c4bd","quote":"Every morning is a blank page, and you're still holding the pen.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Mỗi buổi sáng là một trang giấy trắng, và bạn vẫn đang cầm bút.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"11040617-d463-4105-88b3-fa18b1e1ca13","quote":"You haven't been left behind; you're just on a road unlike anyone else's.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn không bị bỏ lại phía sau, bạn chỉ đang đi trên con đường không ai giống ai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6454a78f-e18d-47c0-9d97-166bb6a425a5","quote":"One small step a day, and one day you'll look back and not believe how far you've come.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Mỗi ngày tiến một bước nhỏ, rồi một ngày bạn sẽ ngoảnh lại và không tin nổi mình đã đi xa đến vậy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7aba527f-9a1c-47e2-ac29-45481a13ec63","quote":"Don't look down on days when you only did a little. A little every day adds up to a lot.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Đừng coi thường những ngày chỉ làm được một chút. Một chút mỗi ngày cộng lại thành rất nhiều.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"dcba9832-8806-4c84-a86e-ade08f78d511","quote":"Every mountain is climbed one ordinary step at a time.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Ngọn núi nào cũng được leo bằng từng bước chân bình thường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"fa4f4588-17e7-492f-8297-3d4266685db2","quote":"You don't need to change your whole life overnight. Just change one habit this week.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Bạn không cần thay đổi cả cuộc đời trong một đêm. Chỉ cần thay đổi một thói quen trong tuần này.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9c7dad12-c6a1-49f4-b2fb-23d289d565e7","quote":"Trees don't grow overnight, and neither do you. Be patient with your own growth.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Cây không lớn trong một đêm, và bạn cũng vậy. Hãy kiên nhẫn với sự lớn lên của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"bdb45ab4-7e10-469d-9948-185a91325cf4","quote":"A slow step beats standing still, and resting beats turning back and quitting.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Bước chậm vẫn hơn đứng yên, và đứng yên nghỉ ngơi vẫn hơn quay lưng bỏ cuộc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"74c57953-1921-463a-aabd-24c9e9d7f888","quote":"Some seeds stay underground a long time before sprouting. You're growing roots too.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Có những hạt giống nằm rất lâu dưới đất trước khi nảy mầm. Bạn cũng đang mọc rễ đấy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7caa20ee-5921-46dd-a83a-a7226149929b","quote":"What you plant today may not bear fruit yet, but none of it is wasted.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Những gì bạn gieo hôm nay có thể chưa thấy quả, nhưng không có gì là uổng phí.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3c8848c5-e682-4c75-bbbe-009c844dabee","quote":"You're improving every day; some progress just doesn't make noise.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Ngày nào bạn cũng tiến bộ, chỉ là có những tiến bộ không ồn ào.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ad1c36d0-45f3-4095-afcc-14979b9b4bce","quote":"Walking slowly is fine, as long as every step is yours.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Đi chậm cũng được, miễn là mỗi bước đều là của bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ae1b2d57-b202-4356-8150-ad4b7375f8b3","quote":"Success doesn't come from one explosive day, but from a hundred quiet days of effort.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Thành công không đến từ một ngày bùng nổ, mà từ trăm ngày lặng lẽ cố gắng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a044a45e-f458-4410-9498-9e24ffe5bc19","quote":"Be a little patient with yourself. Some good things need a long time to ripen.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Kiên nhẫn với mình một chút. Có những điều tốt đẹp cần nhiều thời gian để chín.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e11d45b1-a7c5-4055-a940-10ae0625817a","quote":"Not managing it yesterday doesn't mean you can't today.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Hôm qua bạn chưa làm được, không có nghĩa là hôm nay bạn không thể.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c061fbea-e62f-4150-80c4-33c639481992","quote":"You haven't missed any train. Yours is still on its way to the station.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn không trễ chuyến tàu nào cả. Chuyến của bạn vẫn đang trên đường đến ga.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"74eb22e9-cb11-4850-a274-c190cdf78156","quote":"Starting over isn't shameful. What's sad is never daring to start.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bắt đầu lại không đáng xấu hổ. Đáng tiếc là không bao giờ dám bắt đầu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"156acf2b-4379-4480-94ab-800f0ac98dad","quote":"As long as you're breathing, you can still rewrite your story.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Còn hơi thở là còn cơ hội viết lại câu chuyện của mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"19dc4be6-4e16-4330-9c02-a7d6ce3b0d1a","quote":"You may not be where you want to be, but you're no longer where you used to stand.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn có thể chưa ở nơi mình muốn, nhưng bạn không còn ở nơi mình từng đứng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1d8be1ee-5ff5-4d64-b575-ee4eb0545687","quote":"Every new day is an invitation: try one more time.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Mỗi ngày mới là một lời mời: hãy thử thêm một lần nữa.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"986ed2c5-7332-4bb3-8235-cfe66485f1d9","quote":"If today is just a little better than yesterday, you're heading the right way.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Chỉ cần hôm nay tốt hơn hôm qua một chút, thế là bạn đang đi đúng hướng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2c0737a8-90d3-4cd3-b7f6-3d49a5e05c0b","quote":"Don't lose heart when you see no results. Roots always grow before the trunk rises.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Đừng nản khi chưa thấy kết quả. Rễ cây luôn lớn trước khi thân cây vươn lên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8a64ce9d-888f-48ee-8008-5a5eaa7beb21","quote":"Some days, not giving up is progress enough.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Có những ngày bạn chỉ cần không bỏ cuộc, và như thế đã là tiến bộ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2dd293d2-83f2-41ab-bbf6-0c07aab91856","quote":"The first brick always looks small, until it becomes a house.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Viên gạch đầu tiên luôn trông nhỏ bé, cho đến khi nó thành một ngôi nhà.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1a3afdc9-252c-4aad-9d7d-9a11b991a68c","quote":"Today's effort is a gift you send to your future self.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Nỗ lực hôm nay là món quà bạn gửi cho chính mình của tương lai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"47335672-f7c3-4640-a664-2f49d3b4d5ae","quote":"You don't need to run fast; you just shouldn't stop for too long.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Bạn không cần chạy nhanh, bạn chỉ cần đừng dừng lại quá lâu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b0c31a73-35dd-47c6-9be3-b3643d0a103f","quote":"No small step is meaningless if it moves you away from where you were.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Không có bước nhỏ nào là vô nghĩa nếu nó đưa bạn ra khỏi chỗ cũ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"9881d628-6042-4075-a85b-7fdabfa09bd6","quote":"Great things often begin with a tiny decision on an ordinary evening.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Những điều lớn lao thường bắt đầu từ một quyết định rất nhỏ trong một buổi tối bình thường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"09bb5555-77e3-4bea-8058-e656af87c1d9","quote":"You're building something no one can see yet. Keep building.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Bạn đang xây một điều gì đó mà chưa ai nhìn thấy. Cứ xây tiếp đi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d75d768f-25a3-4d61-ab68-f5a9b13ef4cc","quote":"Be grateful for the slow days; they teach you endurance.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Hãy biết ơn những ngày chậm chạp, vì chúng dạy bạn sự bền bỉ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"15fdf086-a7ea-4a27-8f99-6b6871f37fa6","quote":"No one is good from the start. Every master was once as clumsy as you are now.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Không ai giỏi ngay từ đầu. Mọi bậc thầy đều từng vụng về như bạn bây giờ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"671f6674-e707-474b-9a87-a032286a640e","quote":"Perseverance isn't never being tired; it's choosing to continue while tired.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Kiên trì không phải là không mệt, mà là mệt vẫn chọn đi tiếp.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"c1c7ec92-8279-4f8c-9990-91a68bcf05e9","quote":"Every page read, every new word learned, every drop of sweat is quietly changing you.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Mỗi trang sách đọc, mỗi từ mới học, mỗi giọt mồ hôi đều đang âm thầm thay đổi bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"16c56c15-4569-4724-8606-4bfb94dab208","quote":"You can learn a language at any age; the world never closes its doors to the curious.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Học một ngoại ngữ ở tuổi nào cũng được, vì thế giới không đóng cửa với ai ham học.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a098177b-4c80-436b-8bd8-ba8e11e34839","quote":"The door to your dream isn't locked; it's just a little heavy. Push a bit harder.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Cánh cửa ước mơ không khóa, nó chỉ hơi nặng một chút. Đẩy thêm đi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2f7efef7-9f2c-4b74-9090-20bf23df9556","quote":"Don't wait for everything to be perfect to begin. Begin, and things will slowly become better.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Đừng đợi mọi thứ hoàn hảo mới bắt đầu. Bắt đầu rồi mọi thứ sẽ dần hoàn hảo.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e664b864-db54-41c9-acea-03c96f34e71d","quote":"You have the rest of your life to start fresh, and it begins right now.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn có cả phần đời còn lại để làm lại từ đầu, và phần đời ấy bắt đầu ngay lúc này.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0dec6f1c-a925-470b-a3ad-7320430c9084","quote":"If you're at the starting line today, congratulations: you've already stood up.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Nếu hôm nay bạn đang ở vạch xuất phát, chúc mừng, bạn đã đứng dậy rồi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"102b9a41-eb0a-400f-90c3-162d386b3aff","quote":"The one who starts last can still run the farthest.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Người về sau vẫn có thể chạy xa nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ee593065-2eb6-444d-b0fa-da69c1c0c10e","quote":"You're in the right place to begin: exactly where you're standing.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn đang ở đúng nơi để bắt đầu: chính là nơi bạn đang đứng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f92ea1d9-d8a7-441a-9a3c-6d9cb246407d","quote":"Being late for success doesn't mean success has forgotten you.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Trễ hẹn với thành công không có nghĩa là thành công đã quên bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2d9cf8cc-73bd-4e24-a2a6-01639df92ebb","quote":"Today's sweat will be tomorrow's smile.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Những giọt mồ hôi hôm nay sẽ là nụ cười của ngày mai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"2cdcaf52-9938-4388-adbf-e8184571f026","quote":"Little by little; no one's asking you to finish everything today.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Từng chút một thôi, không ai bắt bạn phải hoàn thành tất cả trong hôm nay.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"685c9079-4a31-43b2-8ffe-41f4c5dd6f44","quote":"Your effort hasn't paid off yet; it's just collecting interest.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Cố gắng của bạn chưa được đền đáp, chỉ là nó đang tích lũy lãi suất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d17329e1-3519-4ff2-be35-40ba399d2319","quote":"One more word, one more page, one more step. That's how people change their lives.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Học thêm một từ, đọc thêm một trang, đi thêm một bước. Đó là cách người ta thay đổi cuộc đời.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"65008a71-dc11-43da-975e-a9e62835602a","quote":"Don't judge the journey by one bad day. Look at the whole year.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Đừng đánh giá hành trình qua một ngày tồi tệ. Hãy nhìn cả một năm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"6d048e53-8271-4ff9-8658-abdffe2e581c","quote":"The days no one sees you trying are the most important ones.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Những ngày không ai thấy bạn cố gắng, chính là những ngày quan trọng nhất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e1ef3143-748b-43a1-8677-a3690594bebf","quote":"A drop is small, but persistent enough, it becomes a river.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Giọt nước nhỏ, nhưng kiên trì đủ lâu sẽ thành dòng sông.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"526170c4-a05f-4beb-be7b-9904e667aa1c","quote":"You don't need a giant leap, just steady steps.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Không cần một bước nhảy vọt, chỉ cần bước tiếp đều đặn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"245f7a66-a490-4356-9448-6e151e63e4ce","quote":"You're making progress, even when it feels like you're standing still.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Bạn đang tiến bộ, kể cả khi cảm giác như mình đang đứng yên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ed14b7b6-ec0f-45c3-ada3-a903cdf428e0","quote":"Ten percent today, twenty tomorrow. Keep going, and you'll reach a hundred.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Hôm nay làm được 10%, mai 20%. Cứ thế, rồi sẽ đến 100%.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f5c9715f-a473-4fac-a76f-db426c4cd03d","quote":"The sun rises every day, as a reminder that we're always allowed to begin again.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Mặt trời mọc mỗi ngày, như một lời nhắc rằng ta luôn được phép bắt đầu lại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ec400ef2-0a16-4390-a227-1813feef57dd","quote":"You don't have to be fast. Going in the right direction is enough.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Không cần phải nhanh. Chỉ cần đi đúng hướng là đủ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a06322ad-9d49-4ca2-b85d-fac5a99bfd17","quote":"A seed doesn't know it will become a tree; it just keeps growing. So do you.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Hạt giống không biết mình sẽ thành cây, nó chỉ cứ lớn. Bạn cũng vậy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"3d2b223c-ffd5-4790-b579-8f3fb6d5ee1d","quote":"You're not late. You're arriving right on time for your own story.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn chưa muộn. Bạn chỉ đang đến đúng giờ của câu chuyện riêng mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8dc567c4-7504-4ddf-8937-0e099f0862eb","quote":"Some seasons of life are for sowing, not reaping. Don't lose heart while your hands are still empty.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Có những mùa đời chỉ để gieo, chưa phải để gặt. Đừng nản khi tay vẫn còn trống.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f4c01637-750d-4ff5-8061-e56d717275d7","quote":"Wherever you are today, you can still choose your direction for tomorrow.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bất kể hôm nay bạn đang ở đâu, bạn vẫn có thể chọn hướng đi cho ngày mai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b0219bf4-0f30-4928-baed-0e7a6e4b0b5b","quote":"Every morning is another chance to do what you were about to give up on.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Mỗi sáng thức dậy là thêm một cơ hội để làm điều bạn đã định bỏ dở.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"a399cc66-09f6-45c4-9904-ff3dbf909547","quote":"You're not yet who you want to be, but you're on your way there.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Bạn chưa phải là người mình muốn trở thành, nhưng bạn đang trên đường đến đó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b990cc8d-9ec9-420d-b679-ffb563c6fe37","quote":"This world is big enough for your dream, and patient enough to wait until you're ready.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Thế giới này đủ rộng cho ước mơ của bạn, và cũng đủ kiên nhẫn để chờ bạn sẵn sàng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7c3ab957-6407-40ae-9126-3d883d01af87","quote":"A long road isn't as scary as never daring to step onto it.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Đường dài không đáng sợ bằng việc chưa bao giờ dám bước.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e0c387e6-c944-408d-bd5e-d5d91513861e","quote":"Some wonderful things only arrive after you hold on for one more day.","topic":"Từng bước nhỏ","author":null,"status":"approved","meaning":"Có những điều tuyệt vời chỉ đến sau khi bạn kiên trì thêm một ngày nữa.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1e693e45-0930-4855-a088-f04f425e548e","quote":"Don't let yesterday's \"if only\" steal today's \"let's begin\".","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Đừng để những lời \"giá như\" của hôm qua lấy mất hai chữ \"bắt đầu\" của hôm nay.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ab98abae-62ad-4eff-8887-2239bca4cbd2","quote":"Today could be the first day of a new version of you. No one else needs to know; it's enough that you do.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Hôm nay có thể là ngày đầu tiên của một phiên bản mới của bạn. Không cần ai biết, chỉ cần bạn biết là đủ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"320ce3c6-0fe8-4b67-8514-d5fcc117bb47","quote":"People often say \"it's too late,\" but there's only one thing that's truly late: when we no longer want to try.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Người ta hay nói \"muộn rồi\", nhưng thật ra chỉ có một điều thực sự muộn: là khi ta không còn muốn thử nữa.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"7c379661-6fd4-446c-a0a9-7654d9de21aa","quote":"Spring never asks how long winter lasted. It simply comes and blooms. So can you.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Mùa xuân không bao giờ hỏi mùa đông đã kéo dài bao lâu. Nó chỉ đến, và nở hoa. Bạn cũng vậy.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"af93eb49-f149-4bd0-bfcb-9cea786ece96","quote":"You may not choose where you start, but every day you're choosing where you'll end up.","topic":"Không bao giờ là muộn","author":null,"status":"approved","meaning":"Bạn có thể không chọn được nơi mình bắt đầu, nhưng mỗi ngày bạn đều đang chọn nơi mình sẽ đến.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"503d19d6-2d06-43f6-b588-55c841bcd8fc","quote":"You yourself must strive. The Buddhas only point the way.","topic":"Bản thân & Tự tin","author":"Đức Phật","status":"draft","meaning":"Bạn phải tự mình nỗ lực. Chư Phật chỉ là người chỉ đường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d7466cac-eea3-4287-b9ef-6fd3252f6a74","quote":"Be a lamp unto yourself.","topic":"Bản thân & Tự tin","author":"Đức Phật","status":"draft","meaning":"Hãy tự thắp đuốc lên mà đi.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"f59612ae-0c66-4a83-96e7-c4f03483fbf0","quote":"I am the master of my fate, I am the captain of my soul.","topic":"Bản thân & Tự tin","author":"William Ernest Henley","status":"draft","meaning":"Tôi là chủ nhân số phận mình, tôi là thuyền trưởng linh hồn mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"059d047b-947d-46f9-95f8-7fa82ed6104d","quote":"Insist on yourself; never imitate.","topic":"Bản thân & Tự tin","author":"Ralph Waldo Emerson","status":"draft","meaning":"Hãy kiên định với chính mình; đừng bao giờ bắt chước.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4cb5855d-50c8-4b64-a99a-39eae292b8ca","quote":"Every man is the architect of his own fortune.","topic":"Bản thân & Tự tin","author":"Appius Claudius Caecus","status":"draft","meaning":"Mỗi người là kiến trúc sư của vận mệnh chính mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ffc2ebf1-3618-47fa-b722-43477db4661c","quote":"Become who you are.","topic":"Bản thân & Tự tin","author":"Friedrich Nietzsche","status":"draft","meaning":"Hãy trở thành chính mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"4ca4789d-276d-411c-8354-606f0e364078","quote":"One must still have chaos in oneself to be able to give birth to a dancing star.","topic":"Bản thân & Tự tin","author":"Friedrich Nietzsche","status":"draft","meaning":"Phải có hỗn loạn trong mình mới có thể sinh ra một ngôi sao biết nhảy múa.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ed4dc8a3-90cf-407c-b4d7-d5700daf5fc6","quote":"It is not length of life, but depth of life.","topic":"Bản thân & Tự tin","author":"Ralph Waldo Emerson","status":"draft","meaning":"Điều quan trọng không phải độ dài của cuộc đời, mà là chiều sâu của nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"07bc6425-c3d0-4ffb-b813-7ecd6cf34256","quote":"The greatest thing in the world is to know how to belong to oneself.","topic":"Bản thân & Tự tin","author":"Michel de Montaigne","status":"draft","meaning":"Điều vĩ đại nhất trên đời là biết cách thuộc về chính mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"592356a2-0fe9-4aa7-815f-c4594b87a40c","quote":"A man who does not think for himself does not think at all.","topic":"Bản thân & Tự tin","author":"Oscar Wilde","status":"draft","meaning":"Người không tự suy nghĩ thì chẳng suy nghĩ gì cả.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"439da949-e292-4601-8a7b-327c9c25cf6a","quote":"Character is like a tree and reputation like its shadow.","topic":"Bản thân & Tự tin","author":"Abraham Lincoln","status":"draft","meaning":"Nhân cách như cái cây, còn danh tiếng như cái bóng của nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1b7ddb21-54f8-4f61-8efb-1d532349e736","quote":"Rely on your own strength to survive.","topic":"Bản thân & Tự tin","author":"Thành ngữ Việt Nam","status":"draft","meaning":"Tự lực cánh sinh.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"47199555-08b6-4b7f-ba70-b181253369e9","quote":"A good name is better than fine clothes.","topic":"Bản thân & Tự tin","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Tốt danh hơn lành áo.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b427fb94-153d-4956-ae37-00bc69eec830","quote":"Good character beats good looks.","topic":"Bản thân & Tự tin","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Cái nết đánh chết cái đẹp.","date_created":"2026-11-25T02:10:29.662137+00:00"}]$sync$::jsonb) on conflict do nothing;
insert into "review_quotes" ("id", "quote", "meaning", "author", "topic", "status", "date_created") select "id", "quote", "meaning", "author", "topic", "status", "date_created" from jsonb_populate_recordset(null::"review_quotes", $sync$[{"id":"00f25338-31cd-4189-8318-5142965ffaab","quote":"Even hungry, stay clean; even ragged, stay fragrant (keep your dignity).","topic":"Bản thân & Tự tin","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Đói cho sạch, rách cho thơm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b8a52a70-13f7-418b-b782-0b3ae0205d25","quote":"People are the flowers of the earth.","topic":"Bản thân & Tự tin","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Người ta là hoa đất.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"64f54f95-bfeb-4e90-976a-4d99cc1a77d1","quote":"Before judging others, look at yourself.","topic":"Bản thân & Tự tin","author":"Tục ngữ Việt Nam","status":"draft","meaning":"Nói người phải nghĩ đến ta.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5a5b8940-c100-48c0-92de-788843217dac","quote":"The morning has slipped away, but the evening is not too late.","topic":"Không bao giờ là muộn","author":"Vương Bột","status":"draft","meaning":"Buổi sáng đã trôi qua, nhưng buổi chiều vẫn chưa muộn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0da73fa0-ea77-4575-8b39-fbc6f6c9bca5","quote":"Don't say the evening is late; its glow still fills the whole sky.","topic":"Không bao giờ là muộn","author":"Lưu Vũ Tích","status":"draft","meaning":"Đừng nói chiều đã muộn, ráng chiều vẫn rực rỡ khắp trời.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0ec1b161-fe22-4944-925a-02eb184d9f3c","quote":"Sifting a thousand times is hard, but once the wild sand is blown away, gold appears.","topic":"Từng bước nhỏ","author":"Lưu Vũ Tích","status":"draft","meaning":"Đãi nghìn lần lọc vạn lần tuy vất vả, thổi hết cát rồi vàng mới hiện ra.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"e3cfee12-fde6-41de-be51-acdaa8cd19c1","quote":"Do not disturb yourself by picturing your life as a whole.","topic":"Từng bước nhỏ","author":"Marcus Aurelius","status":"draft","meaning":"Đừng tự làm mình bối rối bằng cách hình dung cả cuộc đời cùng một lúc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"29d4429c-df0c-4777-8f6e-461b0724b4f4","quote":"When we do the best that we can, we never know what miracle is wrought in our life, or in the life of another.","topic":"Từng bước nhỏ","author":"Helen Keller","status":"draft","meaning":"Khi ta làm hết sức mình, ta không bao giờ biết phép màu nào đang thành hình trong đời mình hay đời người khác.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"cc2d33e3-f0e5-406a-9a45-693b62039269","quote":"How wonderful it is that nobody need wait a single moment before starting to improve the world.","topic":"Không bao giờ là muộn","author":"Anne Frank","status":"draft","meaning":"Thật tuyệt vời khi không ai cần chờ thêm một khoảnh khắc nào để bắt đầu làm thế giới tốt đẹp hơn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ef87e7c9-a5af-417e-a040-2177bd6ff02e","quote":"Youth does not come twice; a day has only one morning. Strive while there is time, for the years wait for no one.","topic":"Không bao giờ là muộn","author":"Đào Uyên Minh","status":"draft","meaning":"Tuổi xuân không trở lại, một ngày chẳng có hai buổi sớm. Kịp thời hãy gắng sức, năm tháng chẳng đợi ai.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"479f8ab8-a6c9-4667-8c69-6f732b1923dc","quote":"Heaven moves with strength; so the noble person strives without ceasing.","topic":"Từng bước nhỏ","author":"Kinh Dịch","status":"draft","meaning":"Trời vận hành mạnh mẽ, người quân tử theo đó mà tự cường không ngừng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"be46b408-f33d-44d0-86a6-225dde561813","quote":"Do not treasure a golden robe; treasure your youth. When a flower can be picked, pick it, lest you wait and pick only an empty branch.","topic":"Không bao giờ là muộn","author":"Đỗ Thu Nương","status":"draft","meaning":"Chớ tiếc áo kim tuyến, hãy tiếc tuổi xuân. Hoa nở hái được thì hãy hái, đừng đợi hoa tàn chỉ bẻ cành không.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"35081979-805c-4d14-a0b4-9f48c23efb21","quote":"My life has a limit, but knowledge has none.","topic":"Từng bước nhỏ","author":"Trang Tử","status":"draft","meaning":"Đời ta có hạn, mà tri thức thì vô hạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8e097b01-7b6d-42ad-8f94-7b048e85daf4","quote":"O blue stream among the green hills, don't boast of flowing away so fast; once you reach the sea, it will be hard to return.","topic":"Không bao giờ là muộn","author":"Hwang Jini","status":"draft","meaning":"Hỡi dòng suối biếc giữa núi xanh, đừng khoe chảy nhanh; một khi ra biển cả rồi, khó lòng quay lại.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ae0af55b-7ecc-47c6-adb5-574063abe9c2","quote":"Hang on to your youthful enthusiasms; you'll be able to use them better when you're older.","topic":"Không bao giờ là muộn","author":"Seneca","status":"draft","meaning":"Hãy giữ lấy nhiệt huyết tuổi trẻ; khi lớn tuổi hơn, bạn sẽ biết dùng nó tốt hơn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1fe15446-ed5f-4740-baf3-7eff073da053","quote":"Starting at thirty is fine, as long as you're not still waiting at thirty-five.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Ba mươi tuổi mới bắt đầu cũng được, miễn là bạn không để ba mươi lăm tuổi vẫn còn đứng chờ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"8ea516ab-3421-4144-a5bc-c88b1256c9e2","quote":"Some flowers bloom late, but when they do, they're heartbreakingly beautiful.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Có những bông hoa nở muộn, nhưng khi đã nở thì đẹp đến nao lòng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"16a367fd-f0d8-4188-8efd-dac6cac0fe42","quote":"Don't mourn the years that have passed. Make the years ahead leave nothing to regret.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Đừng tiếc những năm đã qua. Hãy để những năm sắp tới không còn gì phải tiếc.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"60fac064-becb-456d-9670-50fe03beadaa","quote":"Some succeed at twenty, some at fifty. Both are right on their own time.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Có người thành công năm hai mươi, có người năm năm mươi. Cả hai đều đúng lúc của họ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"49565055-38d9-490b-9adc-ff6643f6fb75","quote":"If a dream still keeps you up at night, it hasn't expired yet.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Nếu ước mơ vẫn còn làm bạn mất ngủ, thì nó vẫn chưa hết hạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"043e1f7f-af87-410f-b5da-ad6745ec8906","quote":"It's never too late to turn away from a road that isn't meant for you.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Chưa bao giờ là quá trễ để quay đầu khỏi con đường không dành cho mình.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"360288c0-e377-4b6d-b148-b2e5dffe19eb","quote":"Lost time can't be recovered, but the time ahead is still entirely yours.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Thời gian đã mất không lấy lại được, nhưng thời gian phía trước vẫn hoàn toàn là của bạn.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"0bedd2c8-d9f6-46b8-8729-ee09b5f9e85b","quote":"Some people take a very long detour to find themselves. You're not lost; you're on a detour.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Có những người phải đi đường vòng rất xa mới tìm thấy mình. Bạn không lạc, bạn chỉ đang đi đường vòng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"db9b3293-5718-42ed-8825-5a4d910f68f4","quote":"Dreams have no age. Only people who stop believing in them.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Ước mơ không có tuổi. Chỉ có người thôi tin vào nó.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"1eac8f49-32d7-4df4-bb5c-a331740226ab","quote":"Age is just a number on paper; a heart that wants to learn is always young.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Tuổi tác chỉ là con số trên giấy tờ, còn trái tim muốn học thì lúc nào cũng trẻ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"90595fd5-47d7-4a3b-b90f-ee9fa0ca06ae","quote":"Some people learn to swim at forty, then swim across rivers they once feared.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Có người bốn mươi tuổi mới học bơi, rồi bơi qua cả những con sông họ từng sợ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"eec47b39-ef49-453c-a291-6a9a92d99cf6","quote":"Don't let a number convince you that the door has closed.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Đừng để con số tuổi tác thuyết phục bạn rằng cánh cửa đã đóng.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"502e8209-988e-45de-969d-17a9e9a8a973","quote":"Life has many seasons, and yours may not have begun yet.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Cuộc đời có nhiều mùa, và mùa của bạn có thể vẫn chưa bắt đầu.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"922e57fc-4df4-4570-b1bf-fb6eb96ebb85","quote":"Some find their passion at thirty-five. Nothing is late for someone still searching.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Có những người tìm thấy đam mê ở tuổi ba mươi lăm. Không có gì là muộn với người đang tìm.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"ad2b6319-f403-480e-b0e0-9ee19d4af592","quote":"Don't let your youth end just because the years go up.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Hãy để tuổi trẻ của bạn không kết thúc khi tuổi tác tăng lên.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"301bbf2a-8b47-44fd-8c26-c55df58152f6","quote":"The years you spent fumbling aren't lost; they're the foundation for the life ahead.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Những năm tháng loay hoay không mất đi, chúng là nền móng cho phần đời phía trước.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"482cc31d-3f84-45e5-8793-803ad76cc540","quote":"Don't condemn yourself for being lost a few years. Those who get lost know many roads.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Đừng tự kết án mình chỉ vì đã đi lạc vài năm. Người đi lạc mới biết nhiều đường.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d0bb65e8-8468-48e2-9df3-e6b3bb7a709d","quote":"Some people live half their lives before knowing what they want. Knowing early or late is still a gift.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Có những người phải đi qua nửa đời mới biết mình muốn gì. Bạn biết sớm hay muộn đều là món quà.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"5456ef5f-1571-45ff-90d6-30b355b3c6b6","quote":"Every day you're still curious is a day you're still young.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Mỗi ngày bạn còn tò mò, là mỗi ngày bạn còn trẻ.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"253a292a-1c21-4e46-bbfd-b19a551222b0","quote":"There's no \"too old\" for chasing what makes your heart flutter.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Không có lúc nào là \"quá già\" để theo đuổi điều làm tim mình rung động.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"d3210fe1-a694-48d2-8be5-535f79fe6fd8","quote":"It's never too late to apologize, to make a phone call, to love someone.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Không bao giờ quá muộn để nói lời xin lỗi, để gọi một cuộc điện thoại, để thương một người.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"67d57b75-49dc-4c90-8dd6-a292c712bd6a","quote":"Many well-known people succeeded after forty. Your story could be the same.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Nhiều người nổi tiếng thành công sau tuổi bốn mươi. Câu chuyện của bạn có thể cũng thế.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"b5689a40-d788-470d-8635-0f70f36bf32d","quote":"Some lessons come late, some people come late, some chances come late. But late doesn't mean never.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Có những bài học đến muộn, có những người đến muộn, có những cơ hội đến muộn. Nhưng muộn không có nghĩa là không đến.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"86a3a3ce-acb4-4795-94db-97955f304ef2","quote":"You're at the best age to begin, because it's the only age you have right now.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Bạn đang ở độ tuổi đẹp nhất để bắt đầu, vì đó là độ tuổi duy nhất bạn đang có.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"82d94931-ce7c-46e2-907b-487c3dae491b","quote":"You don't need to win today. You just need not to lose to yourself, not to quit before giving it everything.","topic":"Từng bước nhỏ","author":null,"status":"draft","meaning":"Bạn không cần thắng ngay hôm nay. Bạn chỉ cần không thua chính mình, không bỏ cuộc trước khi thử hết sức.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"72a68b23-48c4-4964-9c06-6d88117a17b6","quote":"Don't count the years you've lost. Count the days that remain, and ask yourself what you want to fill them with.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Đừng đếm những năm đã mất. Hãy đếm những ngày còn lại, và tự hỏi mình muốn lấp đầy chúng bằng điều gì.","date_created":"2026-11-25T02:10:29.662137+00:00"},{"id":"05993a6a-1f3c-4d4e-b187-535a5c46fcad","quote":"Not everyone gets an easy start, but everyone has the right to write themselves a beautiful ending.","topic":"Không bao giờ là muộn","author":null,"status":"draft","meaning":"Không phải ai cũng có một khởi đầu thuận lợi, nhưng ai cũng có quyền viết cho mình một đoạn kết đẹp.","date_created":"2026-11-25T02:10:29.662137+00:00"}]$sync$::jsonb) on conflict do nothing;
select setval(s, greatest((select max("id"::text::bigint) from "review_quotes"), 1)) from (select pg_get_serial_sequence('review_quotes', 'id') s) x where s is not null;

